cd specs/001-my-team-ux && mise exec -- node --input-type=module -e '
import fs from "node:fs";import assert from "node:assert/strict";
const t=fs.readFileSync("tasks.md","utf8");
const re=/^- \[ \] T(\d{3})( \[P\])?( \[US[1-4]\])? \S/;
const storyPhases=new Set(["Phase 2","Phase 4","Phase 5","Phase 6"]);
let phase="";const tasks=[];
for(const l of t.split("\n")){const h=l.match(/^## (Phase \d+)/);if(h)phase=h[1];
 if(/^- \[[ x]\]/.test(l)){assert.ok(re.test(l),"bad format "+l.slice(0,50));const m=l.match(re);const id=+m[1];
  assert.equal(!!m[3],storyPhases.has(phase),"story label "+id);tasks.push({id,phase,line:l,story:m[3]?.trim()});}}
tasks.forEach((x,i)=>assert.equal(x.id,i+1,"sequence "+x.id));
const max=tasks.length;
const allRefs=[...t.matchAll(/\bT(\d{3})\b/g)].map(m=>+m[1]);assert.ok(allRefs.every(r=>r>=1&&r<=max),"dangling");
// forward refs inside dependency phrases
const fwd=[];
for(const x of tasks){for(const m of x.line.matchAll(/(Depends on|depends on|After|after|requires|needs)([^.;]*)/g)){for(const r of m[2].matchAll(/T(\d{3})/g)){if(+r[1]>x.id)fwd.push(x.id+" -> T"+r[1]+" ("+m[1]+")");}}}
console.log("tasks",max,"forward dependency refs:",fwd);
const per={};tasks.forEach(x=>per[x.phase]=(per[x.phase]??0)+1);console.log(per,"parallel",tasks.filter(x=>x.line.includes("[P]")).length);
for(const bad of ["Behaviour to confirm","assumption to confirm","chosen here","Known gap"])assert.ok(!t.includes(bad),bad);
' ; cd ../..; git status --short

