import fs from "node:fs";
import assert from "node:assert/strict";

const dir = "/Users/anguswoodman/Desktop/CodingProjects/fpl-tool/specs/001-my-team-ux/";
const t = fs.readFileSync(dir + "tasks.md", "utf8");
const re = /^- \[ \] T(\d{3})( \[P\])?( \[US[1-4]\])? \S/;
const storyPhases = new Set(["Phase 2", "Phase 4", "Phase 5", "Phase 6"]);
let phase = "";
const tasks = [];
for (const l of t.split("\n")) {
  const h = l.match(/^## (Phase \d+)/);
  if (h) phase = h[1];
  if (/^- \[[ x]\]/.test(l)) {
    assert.ok(re.test(l), "bad format " + l.slice(0, 50));
    const m = l.match(re);
    assert.equal(!!m[3], storyPhases.has(phase), "story label " + m[1]);
    tasks.push({ id: +m[1], phase, line: l });
  }
}
tasks.forEach((x, i) => assert.equal(x.id, i + 1, "sequence " + x.id));
const max = tasks.length;
const refs = [...t.matchAll(/\bT(\d{3})\b/g)].map((m) => +m[1]);
assert.ok(refs.every((r) => r >= 1 && r <= max), "dangling ref");

const fwd = [];
for (const x of tasks) {
  for (const m of x.line.matchAll(/(Depends on|depends on|After|after|requires|needs)([^.;]*)/g)) {
    for (const r of m[2].matchAll(/T(\d{3})/g)) {
      if (+r[1] > x.id) fwd.push(`T${x.id} -> T${r[1]} (${m[1]})`);
    }
  }
}
const per = {};
tasks.forEach((x) => (per[x.phase] = (per[x.phase] ?? 0) + 1));
console.log(JSON.stringify({ total: max, per, parallel: tasks.filter((x) => x.line.includes("[P]")).length, forwardDependencyRefs: fwd }, null, 1));
for (const bad of ["Behaviour to confirm", "assumption to confirm", "chosen here", "Known gap"]) {
  assert.ok(!t.includes(bad), "stale: " + bad);
}

// every FR/SC id in spec should be mentioned somewhere in tasks/quickstart or covered by a known mapping
const spec = fs.readFileSync(dir + "spec.md", "utf8");
const frs = [...new Set([...spec.matchAll(/\*\*(FR-\d{3}[a-z]?)\*\*/g)].map((m) => m[1]))];
console.log("FR count", frs.length);

// stale phrases across artifacts
const files = ["spec.md", "plan.md", "research.md", "data-model.md", "quickstart.md", "contracts/transfer-explorer-get.md", "contracts/transfer-preview-get.md", "checklists/requirements.md"];
for (const f of files) {
  const x = fs.readFileSync(dir + f, "utf8");
  for (const bad of ["OPEN DECISION", "Until this is decided", "(non-filtering)", "Behaviour to confirm"]) {
