    model_version: "component_v3",
    projection_run_id: 42,
    generated_at: "2026-08-16T08:10:00+00:00",
    target_gameweek_number: 2,
    starting_xi_points: 40.0,
    captain_adjusted_points: 44.5,
    starting_xi: [1, 3, 4, 5, 6, 8, 9, 10, 11, 13, 14],
    bench_goalkeeper: 2,
