const file = "/Users/anguswoodman/Desktop/CodingProjects/fpl-tool/specs/001-my-team-ux/tasks.md";
const before = fs.readFileSync(file, "utf8");

// Single pass: T027a -> T028; T028..T065 -> T029..T066; everything else unchanged.
const after = before.replace(/\bT027a\b|\bT(\d{3})\b/g, (match, digits) => {
  if (match === "T027a") return "T028";
  const n = Number(digits);
  return n >= 28 ? `T${String(n + 1).padStart(3, "0")}` : match;
});
assert.ok(!/T\d{3}a/.test(after), "lettered ID remains");
fs.writeFileSync(file, after);

// Validation
const lineRe = /^- \[([ X])\] T(\d{3})( \[P\])?( \[US[1-4]\])? \S/;
const ids = [];
const checked = [];
for (const l of after.split("\n")) {
  if (/^- \[[ X]\]/.test(l)) {
    const m = l.match(lineRe);
    assert.ok(m, "bad task line: " + l.slice(0, 60));
    ids.push(+m[2]);
    checked.push(m[1] === "X");
  }
}
assert.equal(ids.length, 66, "task count");
assert.equal(new Set(ids).size, 66, "unique ids");
ids.forEach((id, i) => assert.equal(id, i + 1, "sequential at " + id));
assert.equal(checked.filter(Boolean).length, 13, "checked count");
assert.ok(checked.slice(0, 13).every(Boolean) && checked.slice(13).every((c) => !c), "checkbox state");
const refs = [...after.matchAll(/\bT(\d{3})\b/g)].map((m) => +m[1]);
assert.ok(refs.every((r) => r >= 1 && r <= 66), "dangling reference");

// Compare old -> new task bodies (ignoring the id numbers) to prove meaning is unchanged.
const strip = (s) => s.replace(/\bT027a\b|\bT\d{3}\b/g, "T#");
assert.equal(strip(before), strip(after), "non-id text changed");
console.log("renumber ok: 66 sequential unique IDs; checkbox state preserved (T001-T013 [X])");

