const snap = () => page.evaluate(async () => JSON.stringify(await (await fetch('http://127.0.0.1:8000/my-team')).json()));
const before = await snap();
const requests = [];
page.on('request', (r) => { if (r.method() !== 'GET') requests.push(`${r.method()} ${r.url()}`); });
await page.getByText('Replacing King').waitFor({ timeout: 60000 });
await page.waitForSelector('tbody tr');
const rows = await page.$$eval('tbody tr', (trs) => trs.map((tr) => ({ name: tr.querySelector('td')?.textContent?.trim(), availability: tr.getAttribute('data-availability'), cells: Array.from(tr.querySelectorAll('td')).slice(1, 8).map((td) => td.textContent?.trim()) })));
const names = rows.map((r) => r.name);
const unavailable = rows.filter((r) => r.availability === 'unavailable').slice(0, 3);
const flagged = rows.filter((r) => /Injured|Doubtful|Suspended/.test(r.name ?? '')).slice(0, 3);
const interleaved = rows.slice(0, 10).map((r) => `${r.name?.slice(0, 20)}|${r.availability}`);
const absent = { Lynch: names.some((n) => n?.startsWith('Lynch')), King: names.some((n) => n?.startsWith('King')), Jackson: names.some((n) => n?.startsWith('N.Jackson')) };
return { total: rows.length, unavailableCount: rows.filter((r) => r.availability === 'unavailable').length, unavailable, flagged, interleaved, absent, squadUnchanged: before === (await snap()), requests };

