await page.waitForSelector('article', { timeout: 60000 });
await page.getByRole('button', { name: 'Select Forster' }).waitFor({ timeout: 60000 });
const snap = () => page.evaluate(async () => JSON.stringify(await (await fetch('http://127.0.0.1:8000/my-team')).json()));
const before = await snap();
const requests = [];
page.on('request', (r) => { if (r.method() !== 'GET') requests.push(`${r.method()} ${r.url()}`); });
const state = async () => page.evaluate(() => {
  const text = (sel) => Array.from(document.querySelectorAll(sel)).map((e) => e.textContent?.trim());
  const all = Array.from(document.querySelectorAll('p'));
  return {
    perPlayerXpts: all.filter((p) => /^GW xPts:/.test(p.textContent ?? '')).length,
    horizonCards: all.filter((p) => /^[135] GW xPts$/.test(p.textContent?.trim() ?? '')).length,
    thisGameweekPanel: all.some((p) => false) || Array.from(document.querySelectorAll('h3')).some((h) => /This Gameweek/.test(h.textContent ?? '')),
    currentRecommendedToggle: Array.from(document.querySelectorAll('button')).filter((b) => ['Current', 'Recommended'].includes(b.textContent?.trim() ?? '')).length,
    opponents: all.filter((p) => /^Opponent:/.test(p.textContent ?? '')).length,
    controls: { optimiser: !!document.querySelector('select[aria-label="Optimise starting 11 by"]'), prev: Array.from(document.querySelectorAll('button')).some((b) => b.textContent?.trim() === 'Previous Game'), refresh: Array.from(document.querySelectorAll('button')).some((b) => b.textContent?.trim() === 'Refresh xPts') },
    toggleLabel: Array.from(document.querySelectorAll('button')).map((b) => b.textContent?.trim()).find((t) => /projected points/.test(t ?? '')),
  };
});
const out = {};
out.initial = await state();
await page.getByRole('button', { name: 'Show projected points' }).click();
await page.waitForTimeout(500);
out.revealed = await state();
await page.getByRole('button', { name: 'Recommended' }).click().catch(() => {});
out.recommendedHeading = await page.getByText('Recommended Starting XI').count();
await page.getByRole('button', { name: 'Hide projected points' }).click();
await page.waitForTimeout(300);
out.hiddenAgain = await state();
out.recommendedAfterHide = await page.getByText('Recommended Starting XI').count();
await page.getByRole('button', { name: 'Show projected points' }).click();
await page.reload();
await page.getByRole('button', { name: 'Select Forster' }).waitFor({ timeout: 60000 });
out.afterReload = await state();
out.storage = await page.evaluate(() => ({ local: localStorage.length, session: sessionStorage.length, cookie: document.cookie }));
out.squadUnchanged = before === (await snap());
out.nonGet = requests;
return out;

