from __future__ import annotations

from dataclasses import replace
from uuid import UUID

from fpl_engine.domain import PlayerPosition
from fpl_engine.rules import SquadSlot, validate_squad

POSITIONS = (
    PlayerPosition.GOALKEEPER,
    *([PlayerPosition.DEFENDER] * 4),
    *([PlayerPosition.MIDFIELDER] * 4),
    *([PlayerPosition.FORWARD] * 2),
    PlayerPosition.GOALKEEPER,
    PlayerPosition.DEFENDER,
    PlayerPosition.MIDFIELDER,
    PlayerPosition.FORWARD,
)


def identity(number: int) -> UUID:
    return UUID(int=number)


def build_players() -> dict[int, SquadSlot]:
    players = {
        index + 1: SquadSlot(
            player_id=index + 1,
            position=position,
            team_id=index % 5 + 1,
            is_starting=index < 11,
            bench_order=None if index < 11 else index - 10,
            is_captain=index == 1,
            is_vice_captain=index == 2,
        )
        for index, position in enumerate(POSITIONS)
    }
    return players | {
        player_id + 100: replace(player, player_id=player_id + 100, team_id=20 + player_id)
        for player_id, player in players.items()
    }


def test_fixture_is_a_legal_multi_club_squad() -> None:
    players = build_players()
    validate_squad(list(players.values())[:15])
    assert len({player.team_id for player in list(players.values())[:15]}) == 5
    assert players[102].position == players[2].position
    assert identity(1) == UUID("00000000-0000-0000-0000-000000000001")

export function plannerIdentity(value: number): string {
  return `00000000-0000-0000-0000-${value.toString(16).padStart(12, "0")}`;
}

export function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

export const frozenPlannerQuote = {
  outgoing_market_tenths: 54,
  incoming_price_tenths: 50,
  source: "stored_player_observation",
  observed_at: "2026-10-14T12:00:00+00:00",
  origin: "captured",
} as const;

export function createPlannerFixture<Plan extends { revision: number }, Intent>(
  initial: Plan,
  apply: (plan: Plan, intents: Intent[]) => Plan,
) {
  let plan = structuredClone(initial);
  const receipts = new Map<
    string,
    { digest: string; status: "validated_pending" | "committed"; committed_revision?: number }
  >();
  const requests: { mutation_id: string; expected_revision: number; intents: Intent[] }[] = [];
  return {
    receipts,
    requests,
    read: () => structuredClone(plan),
    mutate(envelope: (typeof requests)[number]) {
      requests.push(structuredClone(envelope));
      const digest = JSON.stringify(envelope);
      const prior = receipts.get(envelope.mutation_id);
      if (prior && prior.digest !== digest) throw new Error("mutation_id_reused");
      if (prior?.status === "committed") {
        return { status: "already_committed", committed_revision: prior.committed_revision, plan };
      }
      if (envelope.expected_revision !== plan.revision) throw new Error("revision_conflict");
      receipts.set(envelope.mutation_id, { digest, status: "validated_pending" });
      plan = { ...apply(structuredClone(plan), envelope.intents), revision: plan.revision + 1 };
      receipts.set(envelope.mutation_id, {
        digest,
        status: "committed",
        committed_revision: plan.revision,
      });
      return { status: "committed", committed_revision: plan.revision, plan: structuredClone(plan) };
    },
  };
}

