  free_transfers_available: number | null;
  unlimited_transfers: boolean;
  transfers_made: number | null;
  points_hit: number | null;
  starting_points: number | null;
  bench_points: number | null;
  captain_bonus_points: number | null;
  total_points: number | null;
  players: PlanPlayer[];
  transfers_in: PlanTransfer[];
  transfers_out: PlanTransfer[];
  decisions: PlanDecision[];
  accounting: { starting_bank_tenths: number | null; closing_bank_tenths: number | null;
    free_transfers_available: number | null; next_free_transfers: number | null;
    unlimited_transfers: boolean; transfers_made: number | null; points_hit: number | null } | null;
  chip_availability: Partial<Record<PlanChip, PlanChipAvailability>>;
  legal_rearrangements: { first_player_id: number; second_player_id: number;
    kind: "substitution" | "bench_priority" }[];
  evaluation_status: "complete" | "blocked";
};

export type PlanResponse = {
  plan_id: number;
  name: string;
  start_gameweek: number;
  end_gameweek: number;
  initial_bank: number;
  initial_free_transfers: number;
  total_points: number | null;
  total_points_hit: number | null;
  gameweeks: PlanGameweek[];
  revision: number;
  evaluator_version: string;
  foundation_state: "legacy_pending" | "ready";
  starting_state: StartingState | null;
  financial_status: { provisional?: boolean; requires_resolution?: boolean;
    earliest_shortfall_gameweek?: number | null;
    gameweeks?: { gameweek_number: number; shortfall_tenths: number | null; affected_chain: number[] }[] };
  decision_errors: { code: string; message: string; gameweek_number: number;
    decision_id: string | null; conflicting_gameweek: number | null; player_id: number | null }[];
  initialization: { ready: boolean; reason?: string; retryable?: boolean; boundary_origin?: string };
};

export type PlanIntent =
  | { kind: "rename_plan"; name: string }
  | { kind: "change_horizon"; start_gameweek: number; end_gameweek: number;
      used_chips?: PlanChip[]; free_hit_gameweek_19?: boolean }
  | { kind: "set_starting_transfers"; value: number | null }
  | { kind: "set_starting_chips"; used_chips: PlanChip[]; free_hit_gameweek_19: boolean }
  | { kind: "correct_purchase_price"; ownership_id: string; price_tenths: number }
  | { kind: "confirm_purchase_price"; ownership_id: string }
  | { kind: "change_captain" | "change_vice_captain"; gameweek_number: number; player_id: number }
  | { kind: "swap_lineup_players"; gameweek_number: number; first_player_id: number; second_player_id: number }
  | { kind: "activate_chip" | "remove_chip"; gameweek_number: number; chip: PlanChip; expected_chip?: PlanChip | null }
  | { kind: "move_chip"; source_gameweek: number; target_gameweek: number; chip: PlanChip }
  | { kind: "add_transfer"; gameweek_number: number; outgoing_player_id: number;
      outgoing_ownership_id: string; incoming_player_id: number }
  | { kind: "edit_transfer"; decision_id: string; outgoing_player_id?: number;
      outgoing_ownership_id?: string; incoming_player_id?: number }
  | { kind: "remove_transfer"; decision_id: string };

export type PlanMutationEnvelope = { mutation_id: string; expected_revision: number; intents: PlanIntent[] };
export type PlanMutationResponse = { status: "committed" | "already_committed" | "accepted_not_saved";
  mutation_id: string; committed_revision: number | null; plan: PlanResponse; candidate: PlanResponse | null };
export type PlannerErrorDetail = { code: string; message: string; mutation_id?: string;
  plan?: PlanResponse | null; candidate?: PlanResponse | null; intent_metadata?: unknown;
  diagnostics?: PlanResponse["decision_errors"] };

export class PlannerMutationError extends Error {
  constructor(readonly status: number, readonly detail: PlannerErrorDetail) {
    super(detail.message);
    this.name = "PlannerMutationError";
  }
}

export type SavePlanGameweekRequest = {
  chip: PlanChip | null;
  players: SaveMyTeamPlayerSelection[];
};

export class PlanRuleError extends Error {
  readonly code: string;

  constructor(code: string, message: string) {
    super(message);
    this.name = "PlanRuleError";
    this.code = code;
  }
}

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL ?? "http://127.0.0.1:8000";

export async function fetchPlayers(params: {
  search?: string;
  position?: "GK" | "DEF" | "MID" | "FWD";
  status?: string;
  sort?: "web_name" | "price_desc" | "price_asc";
  page?: number;
  page_size?: number;
}): Promise<PlayerListResponse> {
  const query = new URLSearchParams();

  if (params.search) query.set("search", params.search);
  if (params.position) query.set("position", params.position);
  if (params.status) query.set("status", params.status);
  if (params.sort) query.set("sort", params.sort);
  if (params.page) query.set("page", String(params.page));
  if (params.page_size) query.set("page_size", String(params.page_size));

  const response = await fetch(`${API_BASE_URL}/players?${query.toString()}`);
  if (!response.ok) {
    throw new Error(`Players request failed with status ${response.status}`);
  }

  return (await response.json()) as PlayerListResponse;
}

