export function createPlannerFixture<Plan extends { revision: number }, Intent>(
  initial: Plan,
  apply: (plan: Plan, intents: Intent[]) => Plan,
) {
  let plan = structuredClone(initial);
  const receipts = new Map<
    string,
    { digest: string; status: "validated_pending" | "committed"; committed_revision?: number }
  >();
  const requests: { mutation_id: string; expected_revision: number; intents: Intent[] }[] = [];
  return {
    receipts,
    requests,
    read: () => structuredClone(plan),
    mutate(envelope: (typeof requests)[number]) {
      requests.push(structuredClone(envelope));
      const digest = JSON.stringify(envelope);
      const prior = receipts.get(envelope.mutation_id);
      if (prior && prior.digest !== digest) throw new Error("mutation_id_reused");
      if (prior?.status === "committed") {
        return { status: "already_committed" as const, committed_revision: prior.committed_revision ?? null, plan };
      }
      if (envelope.expected_revision !== plan.revision) throw new Error("revision_conflict");
      receipts.set(envelope.mutation_id, { digest, status: "validated_pending" });
      plan = { ...apply(structuredClone(plan), envelope.intents), revision: plan.revision + 1 };
      receipts.set(envelope.mutation_id, {
        digest,
        status: "committed",
        committed_revision: plan.revision,
      });
      return { status: "committed" as const, committed_revision: plan.revision, plan: structuredClone(plan) };
    },
  };
}

import { waitFor } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import { PlanIntent, PlanMutationEnvelope, PlannerMutationError } from "@/lib/api";
import { PlanSaveCoordinator } from "@/lib/plan-save-coordinator";
import { buildPlannerPlan, createPlannerFixture, deferred } from "../fixtures/planner";

describe("PlanSaveCoordinator", () => {
  it("dispatches field-only queued edits at the latest acknowledged revision", async () => {
    const initial = buildPlannerPlan();
    const release = deferred<void>();
    const server = createPlannerFixture(initial, (plan, intents: PlanIntent[]) => ({
      ...plan, name: intents[0].kind === "rename_plan" ? intents[0].name : plan.name,
    }));
    const send = vi.fn(async (planId: number, envelope: PlanMutationEnvelope) => {
      if (send.mock.calls.length === 1) await release.promise;
      return { ...server.mutate(envelope), mutation_id: envelope.mutation_id, candidate: null };
    });
    const coordinator = new PlanSaveCoordinator(initial, { send });
    coordinator.enqueue([{ kind: "change_captain", gameweek_number: 12, player_id: 4 }]);
    coordinator.enqueue([{ kind: "change_vice_captain", gameweek_number: 12, player_id: 5 }]);
    expect(send).toHaveBeenCalledTimes(1);
    const first = structuredClone(send.mock.calls[0][1]);
    expect(coordinator.getSnapshot().acknowledged.revision).toBe(0);
    release.resolve();
    await waitFor(() => expect(coordinator.getSnapshot().status).toBe("saved"));
    expect(send).toHaveBeenCalledTimes(2);
    expect(send.mock.calls[0][1]).toEqual(first);
    expect(send.mock.calls[1][1]).toMatchObject({ expected_revision: 1,
      intents: [{ kind: "change_vice_captain", gameweek_number: 12, player_id: 5 }] });
    expect(coordinator.getSnapshot().acknowledged.revision).toBe(2);
  });

  it("keeps accepted unsaved state and pauses dependent edits until same-ID retry", async () => {
    const initial = buildPlannerPlan();
    const candidate = { ...initial, name: "Accepted name" };
    const server = createPlannerFixture(initial, (plan) => ({ ...plan, name: "Accepted name" }));
    const send = vi.fn(async (planId: number, envelope: PlanMutationEnvelope) => ({
      ...server.mutate(envelope), mutation_id: envelope.mutation_id, candidate: null,
    })).mockRejectedValueOnce(new PlannerMutationError(503, {
      code: "accepted_not_saved", message: "Accepted edit is not saved", plan: initial, candidate,
    }));
    const coordinator = new PlanSaveCoordinator(initial, { send });
    coordinator.enqueue([{ kind: "rename_plan", name: "Accepted name" }]);
    await waitFor(() => expect(coordinator.getSnapshot().status).toBe("not_saved"));
    coordinator.enqueue([{ kind: "change_captain", gameweek_number: 13, player_id: 4 }]);
    expect(send).toHaveBeenCalledTimes(1);
    expect(coordinator.getSnapshot().displayPlan.name).toBe("Accepted name");
    const frozen = structuredClone(send.mock.calls[0][1]);
    coordinator.retry();
    await waitFor(() => expect(coordinator.getSnapshot().status).toBe("saved"));
    expect(send.mock.calls[1][1]).toEqual(frozen);
    expect(send.mock.calls[2][1].expected_revision).toBe(1);
  });

  it("reconciles lost responses using the original ID and never commits twice", async () => {
    const initial = buildPlannerPlan();
    const server = createPlannerFixture(initial, (plan) => ({ ...plan, name: "Committed" }));
    const send = vi.fn(async (planId: number, envelope: PlanMutationEnvelope) => {
      const result = server.mutate(envelope);
      if (send.mock.calls.length === 1) throw new Error("Response lost");
      return { ...result, mutation_id: envelope.mutation_id, candidate: null };
    });
    const coordinator = new PlanSaveCoordinator(initial, { send });
    coordinator.enqueue([{ kind: "rename_plan", name: "Committed" }]);
    await waitFor(() => expect(coordinator.getSnapshot().status).toBe("not_saved"));
    coordinator.retry();
    await waitFor(() => expect(coordinator.getSnapshot().status).toBe("saved"));
    expect(send.mock.calls[1][1]).toEqual(send.mock.calls[0][1]);
    expect(server.read().revision).toBe(1);
  });

  it("retains stale conflict context without blind overwrite or PATCH fallback", async () => {
    const initial = buildPlannerPlan();
    const send = vi.fn().mockRejectedValue(new PlannerMutationError(409, {
      code: "revision_conflict", message: "Plan revision has advanced", plan: { ...initial, revision: 1 },
    }));
    const coordinator = new PlanSaveCoordinator(initial, { send });
    coordinator.enqueue([{ kind: "rename_plan", name: "Local" }]);
    await waitFor(() => expect(coordinator.getSnapshot().status).toBe("conflict"));
    coordinator.enqueue([{ kind: "change_captain", gameweek_number: 12, player_id: 4 }]);
    expect(send).toHaveBeenCalledTimes(1);
    expect(coordinator.getSnapshot().inFlight?.intents).toEqual([{ kind: "rename_plan", name: "Local" }]);
  });
});

import {
  PlanChip, PlanIntent, PlanMutationEnvelope, PlanMutationResponse, PlanResponse,
  PlannerMutationError, fetchPlan, fetchPlanMutation, mutatePlan,
} from "@/lib/api";

export type QueuedPlanIntent = PlanIntent
  | { kind: "set_horizon_bound"; field: "start_gameweek" | "end_gameweek"; value: number }
  | { kind: "set_starting_chip"; chip: PlanChip; used: boolean }
  | { kind: "set_free_hit_19"; used: boolean };

export type PlanSaveSnapshot = {
  acknowledged: PlanResponse;
  displayPlan: PlanResponse;
  inFlight: PlanMutationEnvelope | null;
  pendingCount: number;
  status: "saved" | "saving" | "not_saved" | "conflict" | "error";
  message: string | null;
};

type Transport = {
  send: (planId: number, envelope: PlanMutationEnvelope) => Promise<PlanMutationResponse>;
  receipt: (planId: number, mutationId: string) => Promise<PlanMutationResponse>;
  load: (planId: number) => Promise<PlanResponse | null>;
};

export class PlanSaveCoordinator {
  private snapshot: PlanSaveSnapshot;
  private queue: QueuedPlanIntent[][] = [];
  private active: PlanMutationEnvelope | null = null;
  private listeners = new Set<() => void>();
  private transport: Transport;

  constructor(plan: PlanResponse, transport: Partial<Transport> = {}) {
    this.snapshot = { acknowledged: plan, displayPlan: plan, inFlight: null,
      pendingCount: 0, status: "saved", message: null };
    this.transport = { send: mutatePlan, receipt: fetchPlanMutation, load: fetchPlan, ...transport };
  }

  getSnapshot = (): PlanSaveSnapshot => this.snapshot;

  subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  private publish(change: Partial<PlanSaveSnapshot>): void {
    this.snapshot = { ...this.snapshot, ...change, inFlight: this.active,
      pendingCount: this.queue.reduce((count, batch) => count + batch.length, 0) };
    this.listeners.forEach((listener) => listener());
  }

  synchronize(plan: PlanResponse): void {
    if (!this.active && this.queue.length === 0 && plan.revision >= this.snapshot.acknowledged.revision) {
      this.publish({ acknowledged: plan, displayPlan: plan });
    }
  }

  enqueue(intents: QueuedPlanIntent[]): void {
    if (this.snapshot.acknowledged.foundation_state !== "ready") {
      this.publish({ status: "error", message: "Plan requires explicit initialization before editing" });
      return;
    }
    if (intents.length === 0) return;
    this.queue.push(structuredClone(intents));
    this.publish({});
    this.drain();
  }

  private resolve(intent: QueuedPlanIntent): PlanIntent {
    const plan = this.snapshot.acknowledged;
    if (intent.kind === "set_horizon_bound") {
      return { kind: "change_horizon", start_gameweek: plan.start_gameweek,
        end_gameweek: plan.end_gameweek, [intent.field]: intent.value };
    }
    if (intent.kind === "set_starting_chip" || intent.kind === "set_free_hit_19") {
      const boundary = plan.starting_state;
      if (!boundary) throw new Error("Starting state is unavailable");
      const chips = new Set(boundary.used_chips);
      if (intent.kind === "set_starting_chip") {
        if (intent.used) chips.add(intent.chip);
        else chips.delete(intent.chip);
      }
      return { kind: "set_starting_chips", used_chips: [...chips],
        free_hit_gameweek_19: intent.kind === "set_free_hit_19" ? intent.used : boundary.free_hit_gameweek_19 };
    }
    if ("gameweek_number" in intent) {
      const week = plan.gameweeks.find((item) => item.gameweek_number === intent.gameweek_number);
      if (!week) throw new Error("Selected gameweek is no longer in the plan");
      const selectedIds = "player_id" in intent ? [intent.player_id]
        : intent.kind === "swap_lineup_players" ? [intent.first_player_id, intent.second_player_id]
        : intent.kind === "add_transfer" ? [intent.outgoing_player_id] : [];
      if (selectedIds.some((identifier) => !week.players.some((player) => player.player_id === identifier))) {
        throw new Error("Selected player is no longer owned; select the intended player again");
      }
    }
    return intent;
  }

  private drain(): void {
    if (this.active || this.queue.length === 0) return;
    const batch = this.queue.shift()!;
    try {
      const envelope: PlanMutationEnvelope = { mutation_id: crypto.randomUUID(),
        expected_revision: this.snapshot.acknowledged.revision,
        intents: batch.map((intent) => this.resolve(intent)) };
      envelope.intents.forEach((intent) => Object.freeze(intent));
      Object.freeze(envelope.intents);
      this.active = Object.freeze(envelope);
    } catch (error) {
      this.publish({ status: "error", message: error instanceof Error ? error.message : "Edit cannot be applied" });
      return;
    }
    this.publish({ status: "saving", message: null });
    void this.dispatch();
  }

  private accept(result: PlanMutationResponse): void {
    if (!this.active || result.mutation_id !== this.active.mutation_id
        || result.plan.plan_id !== this.snapshot.acknowledged.plan_id) {
      throw new Error("Mutation acknowledgement does not match the pending edit");
    }
    if (result.status === "accepted_not_saved") {
      this.publish({ displayPlan: result.candidate ?? this.snapshot.acknowledged,
        status: "not_saved", message: "Accepted edit is not saved; retry the same edit" });
      return;
    }
    if (result.committed_revision === null) throw new Error("Committed revision is missing");
    const plan = result.plan.revision >= this.snapshot.acknowledged.revision
      ? result.plan : this.snapshot.acknowledged;
    this.active = null;
    this.publish({ acknowledged: plan, displayPlan: plan, status: "saved", message: null });
    this.drain();
  }

  private fail(error: unknown): void {
    if (error instanceof PlannerMutationError) {
      const { detail } = error;
      if (error.status === 422) {
        this.active = null;
        this.publish({ displayPlan: this.snapshot.acknowledged, status: "error", message: error.message });
        this.drain();
        return;
      }
      if (error.status === 409 || error.status === 404 || error.status === 410) {
        const plan = detail.plan && detail.plan.revision >= this.snapshot.acknowledged.revision
          ? detail.plan : this.snapshot.acknowledged;
        this.publish({ acknowledged: plan, displayPlan: plan, status: "conflict", message: error.message });
        return;
      }
      this.publish({ status: "not_saved", message: error.message,
        displayPlan: detail.code === "accepted_not_saved" && detail.candidate
          && detail.plan?.revision === this.snapshot.acknowledged.revision
          ? detail.candidate : this.snapshot.acknowledged });
      return;
    }
    this.publish({ status: "not_saved", message: "Save outcome is unknown; reconcile or retry the same edit" });
  }

  private async dispatch(): Promise<void> {
    if (!this.active) return;
    const envelope = this.active;
    try {
      const result = await this.transport.send(this.snapshot.acknowledged.plan_id, envelope);
      if (this.active === envelope) this.accept(result);
    } catch (error) {
      if (this.active === envelope) this.fail(error);
    }
  }

  retry(): void {
    if (!this.active || this.snapshot.status !== "not_saved") return;
    this.publish({ status: "saving", message: null });
    void this.dispatch();
  }

  async reconcile(): Promise<void> {
    if (!this.active || this.snapshot.status === "saving") return;
    const envelope = this.active;
    try {
      const result = await this.transport.receipt(this.snapshot.acknowledged.plan_id, envelope.mutation_id);
      if (this.active === envelope) this.accept(result);
    } catch (error) {
      if (this.active === envelope) this.fail(error);
    }
  }

  async revalidate(): Promise<void> {
    if (!this.active || this.snapshot.status !== "conflict") return;
    const envelope = this.active;
    try {
      const plan = await this.transport.load(this.snapshot.acknowledged.plan_id);
      if (!plan) throw new Error("Plan no longer exists");
      if (this.active !== envelope) return;
      this.queue.unshift(structuredClone(envelope.intents));
      this.active = null;
      this.publish({ acknowledged: plan, displayPlan: plan, status: "saved", message: null });
      this.drain();
    } catch (error) {
      this.publish({ status: "conflict", message: error instanceof Error ? error.message : "Revalidation failed" });
    }
  }
}

const coordinators = new Map<number, PlanSaveCoordinator>();

export function getPlanSaveCoordinator(plan: PlanResponse): PlanSaveCoordinator {
  let coordinator = coordinators.get(plan.plan_id);
  if (!coordinator) {
    coordinator = new PlanSaveCoordinator(plan);
    coordinators.set(plan.plan_id, coordinator);
  } else {
    coordinator.synchronize(plan);
  }
  return coordinator;
}

import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { PlansList } from "@/components/plans/plans-list";
import { PlanIntent, PlanMutationEnvelope } from "@/lib/api";
import { buildPlannerPlan, createPlannerFixture } from "../fixtures/planner";

afterEach(() => { cleanup(); vi.restoreAllMocks(); });

function scenario(outcome: "success" | "technical" | "stale") {
  const initial = buildPlannerPlan();
  const server = createPlannerFixture(initial, (plan, intents: PlanIntent[]) => ({
    ...plan, name: intents[0].kind === "rename_plan" ? intents[0].name : plan.name,
  }));
  const requests: { url: string; method: string; body?: PlanMutationEnvelope }[] = [];
  let posts = 0;
  vi.spyOn(global, "fetch").mockImplementation(async (input, init) => {
    const url = String(input);
    const method = init?.method ?? "GET";
    const body = init?.body ? JSON.parse(String(init.body)) : undefined;
    requests.push({ url, method, body });
    if (method === "PATCH" || method === "PUT") return new Response("retired", { status: 410 });
    if (method === "POST" && url.endsWith("/mutations")) {
      posts += 1;
      if (outcome === "stale") return Response.json({ detail: { code: "revision_conflict",
        message: "Plan revision has advanced", plan: { ...initial, revision: 1 } } }, { status: 409 });
      if (outcome === "technical" && posts === 1) return Response.json({ detail: {
        code: "outcome_unknown", message: "Save outcome is unknown" } }, { status: 503 });
      return Response.json({ ...server.mutate(body), mutation_id: body.mutation_id, candidate: null });
    }
    if (url.endsWith("/plans")) return Response.json({ plans: [server.read()] });
    return Response.json(server.read());
  });
  return { requests, initial, server };
}

async function rename(): Promise<void> {
  fireEvent.click(await screen.findByLabelText("Rename Starting state"));
  fireEvent.change(screen.getByRole("textbox", { name: "Rename Starting state" }), {
    target: { value: "Renamed plan" },
  });
  fireEvent.click(screen.getByRole("button", { name: "Save" }));
}

describe("guarded list rename", () => {
  it("loads the current revision, posts a rename intent and refreshes after acknowledgement", async () => {
    const { requests, initial } = scenario("success");
    render(<PlansList />);
    await rename();
    expect(await screen.findByRole("link", { name: "Renamed plan" })).toBeInTheDocument();
    const post = requests.find((request) => request.method === "POST")!;
    expect(post.url).toContain(`/plans/${initial.plan_id}/mutations`);
    expect(post.body).toMatchObject({ expected_revision: 0,
      intents: [{ kind: "rename_plan", name: "Renamed plan" }] });
    expect(requests.slice(0, requests.indexOf(post)).some((request) => request.url.endsWith(`/plans/${initial.plan_id}`))).toBe(true);
    expect(requests.some((request) => request.method === "PATCH")).toBe(false);
  });

  it("shows technical failure and retries the exact same immutable envelope", async () => {
    const { requests } = scenario("technical");
    render(<PlansList />);
    await rename();
    expect(await screen.findByText("Save outcome is unknown")).toBeInTheDocument();
    expect(screen.queryByRole("link", { name: "Renamed plan" })).not.toBeInTheDocument();
    fireEvent.click(screen.getByRole("button", { name: "Retry Rename" }));
    expect(await screen.findByRole("link", { name: "Renamed plan" })).toBeInTheDocument();
    const posts = requests.filter((request) => request.method === "POST");
    expect(posts).toHaveLength(2);
    expect(posts[1].body).toEqual(posts[0].body);
    expect(requests.some((request) => request.method === "PATCH")).toBe(false);
  });

  it("keeps stale rename context visible without claiming success or overwriting", async () => {
    const { requests } = scenario("stale");
    render(<PlansList />);
    await rename();
    expect(await screen.findByText("Plan revision has advanced")).toBeInTheDocument();
    expect(screen.getByRole("textbox", { name: "Rename Starting state" })).toHaveValue("Renamed plan");
    await waitFor(() => expect(requests.filter((request) => request.method === "POST")).toHaveLength(1));
    expect(requests.some((request) => request.method === "PATCH")).toBe(false);
  });
});

"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";

import {
  PlanRuleError,
  PlanSummary,
  createPlan,
  deletePlan,
  fetchPlans,
  fetchPlan,
} from "@/lib/api";
import { PlanSaveCoordinator, PlanSaveSnapshot, getPlanSaveCoordinator } from "@/lib/plan-save-coordinator";

type LoadState =
  | { type: "loading" }
  | { type: "error"; message: string }
  | { type: "loaded"; plans: PlanSummary[] };

const DEFAULT_START_GAMEWEEK = 1;
const DEFAULT_END_GAMEWEEK = 8;

export function PlansList(): JSX.Element {
  const [state, setState] = useState<LoadState>({ type: "loading" });
  const [name, setName] = useState("");
  const [startGameweek, setStartGameweek] = useState(DEFAULT_START_GAMEWEEK);
  const [endGameweek, setEndGameweek] = useState(DEFAULT_END_GAMEWEEK);
  const [actionError, setActionError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [renamingId, setRenamingId] = useState<number | null>(null);
  const [renameValue, setRenameValue] = useState("");
  const [renameCoordinator, setRenameCoordinator] = useState<PlanSaveCoordinator | null>(null);
  const [renameSnapshot, setRenameSnapshot] = useState<PlanSaveSnapshot | null>(null);
  const renameSubscription = useRef<() => void>(() => {});

  useEffect(() => () => renameSubscription.current(), []);

  async function load(): Promise<void> {
    try {
      const response = await fetchPlans();
      setState({ type: "loaded", plans: response.plans });
    } catch (error) {
      setState({
        type: "error",
        message: error instanceof Error ? error.message : "Failed to load plans",
      });
    }
  }

  useEffect(() => {
    void load();
  }, []);

  async function run(action: () => Promise<unknown>): Promise<void> {
    setBusy(true);
    setActionError(null);
    try {
      await action();
      await load();
    } catch (error) {
      setActionError(
        error instanceof PlanRuleError || error instanceof Error
          ? error.message
          : "Something went wrong",
      );
    } finally {
      setBusy(false);
    }
  }

  async function saveRename(planId: number): Promise<void> {
    setBusy(true);
    setActionError(null);
    try {
      const plan = await fetchPlan(planId);
      if (!plan) throw new Error("Plan no longer exists");
      const coordinator = getPlanSaveCoordinator(plan);
      const baseRevision = coordinator.getSnapshot().acknowledged.revision;
      renameSubscription.current();
      setRenameCoordinator(coordinator);
      const observe = () => {
        const snapshot = coordinator.getSnapshot();
        setRenameSnapshot(snapshot);
        setBusy(snapshot.status === "saving");
        setActionError(snapshot.message);
        if (snapshot.status === "saved" && snapshot.acknowledged.revision > baseRevision
            && snapshot.pendingCount === 0 && !snapshot.inFlight) {
          renameSubscription.current();
          setRenamingId(null);
          setRenameCoordinator(null);
          setRenameSnapshot(null);
          void load();
        }
      };
      renameSubscription.current = coordinator.subscribe(observe);
      coordinator.enqueue([{ kind: "rename_plan", name: renameValue.trim() }]);
      observe();
    } catch (error) {
      setBusy(false);
      setActionError(error instanceof Error ? error.message : "Rename failed");
    }
  }

  if (state.type === "loading") {
    return <p className="text-sm text-slate-600">Loading plans...</p>;
  }

  if (state.type === "error") {
    return <p className="text-sm text-red-700">{state.message}</p>;
  }

  return (
    <div className="space-y-6">
      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
        <h2 className="text-lg font-semibold">New plan</h2>
        <p className="mt-1 text-sm text-slate-600">
          A plan starts from your saved team and lets you work gameweek by gameweek.
        </p>
        <div className="mt-4 flex flex-wrap items-end gap-3">
          <label className="flex flex-col gap-1 text-sm text-slate-700">
            Plan name
            <input
              type="text"
              aria-label="Plan name"
              className="w-64 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
              placeholder="No Haaland GW1"
              value={name}
              onChange={(event) => setName(event.target.value)}
            />
          </label>
          <label className="flex flex-col gap-1 text-sm text-slate-700">
            From GW
            <input
              type="number"
              aria-label="Start gameweek"
              min={1}
              max={38}
              className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
              value={startGameweek}
              onChange={(event) => setStartGameweek(Number(event.target.value))}
            />
          </label>
          <label className="flex flex-col gap-1 text-sm text-slate-700">
            To GW
            <input
              type="number"
              aria-label="End gameweek"
              min={1}
              max={38}
              className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
              value={endGameweek}
              onChange={(event) => setEndGameweek(Number(event.target.value))}
            />
          </label>
          <button
            type="button"
            className="rounded-md border border-slate-300 bg-slate-900 px-3 py-2 text-sm font-medium text-white hover:bg-slate-800 disabled:opacity-50"
            disabled={busy || name.trim().length === 0}
            onClick={() =>
              void run(async () => {
                await createPlan({
                  name: name.trim(),
                  start_gameweek: startGameweek,
                  end_gameweek: endGameweek,
                });
                setName("");
              })
            }
          >
            Create Plan
          </button>
        </div>
        {actionError && <p role="alert" className="mt-3 text-sm text-red-700">{actionError}</p>}
        {renameSnapshot?.status === "not_saved" && (
          <button type="button" className="mt-2 rounded-md border px-2 py-1 text-sm"
            onClick={() => renameCoordinator?.retry()}>Retry Rename</button>
        )}
        {renameSnapshot?.status === "conflict" && (
          <button type="button" className="mt-2 rounded-md border px-2 py-1 text-sm"
            onClick={() => void renameCoordinator?.revalidate()}>Revalidate With Current Data</button>
        )}
        {renameSnapshot?.status === "saving" && <p role="status" className="mt-2 text-sm">Saving rename...</p>}
      </section>

      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
        <h2 className="text-lg font-semibold">Your plans</h2>
        {state.plans.length === 0 ? (
          <p className="mt-2 text-sm text-slate-600">No plans yet.</p>
        ) : (
          <ul className="mt-4 space-y-3">
            {state.plans.map((plan) => (
              <li
                key={plan.plan_id}
                className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-slate-200 p-3"
              >
                {renamingId === plan.plan_id ? (
                  <div className="flex flex-wrap items-center gap-2">
                    <input
                      type="text"
                      aria-label={`Rename ${plan.name}`}
                      className="w-64 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
                      value={renameValue}
                      onChange={(event) => setRenameValue(event.target.value)}
                    />
                    <button
                      type="button"
                      className="rounded-md border border-emerald-300 bg-emerald-600 px-2 py-1 text-xs font-medium text-white hover:bg-emerald-500 disabled:opacity-50"
                      disabled={busy || Boolean(renameSnapshot?.inFlight) || renameValue.trim().length === 0}
                      onClick={() => void saveRename(plan.plan_id)}
                    >
                      Save
                    </button>
                    <button
                      type="button"
                      className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-800 hover:bg-slate-50"
                      onClick={() => setRenamingId(null)}
                      disabled={Boolean(renameSnapshot?.inFlight)}
                    >
                      Cancel
                    </button>
                  </div>
                ) : (
                  <div>
                    <Link
                      href={`/plans/${plan.plan_id}`}
                      className="text-sm font-semibold text-slate-900 underline"
                    >
                      {plan.name}
                    </Link>
                    <p className="text-xs text-slate-600">
                      GW {plan.start_gameweek} - GW {plan.end_gameweek}
                    </p>
                  </div>
                )}
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    aria-label={`Rename ${plan.name}`}
                    disabled={busy || Boolean(renameSnapshot?.inFlight)}
                    className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-800 hover:bg-slate-50"
                    onClick={() => {
                      setRenamingId(plan.plan_id);
                      setRenameValue(plan.name);
                    }}
                  >
                    Rename
                  </button>
                  <button
                    type="button"
                    aria-label={`Delete ${plan.name}`}
                    className="rounded-md border border-red-300 bg-white px-2 py-1 text-xs font-medium text-red-700 hover:bg-red-50 disabled:opacity-50"
                    disabled={busy}
                    onClick={() => void run(() => deletePlan(plan.plan_id))}
                  >
                    Delete
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useMemo, useState, useSyncExternalStore } from "react";

import {
  PlanChip,
  PlanGameweek,
  PlanPlayer,
  PlanResponse,
  PlanIntent,
  PlanRuleError,
  PlayerItem,
  SaveMyTeamPlayerSelection,
  fetchPlan,
  fetchPlayers,
} from "@/lib/api";
import { PlanSaveCoordinator, getPlanSaveCoordinator } from "@/lib/plan-save-coordinator";

const EMPTY_SUBSCRIBE = () => () => {};
const EMPTY_SNAPSHOT = () => null;

type Position = "GK" | "DEF" | "MID" | "FWD";

type LoadState =
  | { type: "loading" }
  | { type: "error"; message: string }
  | { type: "missing" }
  | { type: "loaded"; plan: PlanResponse };

const POSITION_ORDER: Position[] = ["GK", "DEF", "MID", "FWD"];
const FORMATION_LIMITS: Record<Position, { min: number; max: number }> = {
  GK: { min: 1, max: 1 },
  DEF: { min: 3, max: 5 },
  MID: { min: 2, max: 5 },
  FWD: { min: 1, max: 3 },
};
const CHIPS: { value: PlanChip; label: string }[] = [
  { value: "WILDCARD", label: "Wildcard" },
  { value: "FREE_HIT", label: "Free Hit" },
  { value: "BENCH_BOOST", label: "Bench Boost" },
  { value: "TRIPLE_CAPTAIN", label: "Triple Captain" },
];
const FIRST_HALF_FINAL_GAMEWEEK = 19;

function seasonHalf(gameweekNumber: number): 1 | 2 {
  return gameweekNumber <= FIRST_HALF_FINAL_GAMEWEEK ? 1 : 2;
}

function chipUsedElsewhereInHalf(
  plan: PlanResponse,
  chip: PlanChip,
  gameweekNumber: number,
): boolean {
  return plan.gameweeks.some(
    (gameweek) =>
      gameweek.chip === chip &&
      gameweek.gameweek_number !== gameweekNumber &&
      seasonHalf(gameweek.gameweek_number) === seasonHalf(gameweekNumber),
  );
}

function formationIsLegal(players: PlanPlayer[]): boolean {
  const counts: Record<Position, number> = { GK: 0, DEF: 0, MID: 0, FWD: 0 };
  for (const player of players.filter((player) => player.is_starting)) {
    counts[player.position] += 1;
  }
  return POSITION_ORDER.every(
    (position) =>
      counts[position] >= FORMATION_LIMITS[position].min &&
      counts[position] <= FORMATION_LIMITS[position].max,
  );
}

function swapStarterWithBench(
  players: PlanPlayer[],
  starterId: number,
  benchId: number,
): PlanPlayer[] {
  const starter = players.find((player) => player.player_id === starterId);
  const bench = players.find((player) => player.player_id === benchId);
  if (!starter || !bench) {
    return players;
  }

  return players.map((player) => {
    if (player.player_id === starterId) {
      return { ...player, is_starting: false, bench_order: bench.bench_order };
    }
    if (player.player_id === benchId) {
      return { ...player, is_starting: true, bench_order: null };
    }
    return player;
  });
}

function toSelections(players: PlanPlayer[]): SaveMyTeamPlayerSelection[] {
  return players.map((player) => ({
    player_id: player.player_id,
    is_starting: player.is_starting,
    bench_order: player.bench_order,
    is_captain: player.is_captain,
    is_vice_captain: player.is_vice_captain,
  }));
}

function toPlanPlayer(item: PlayerItem): PlanPlayer {
  return {
    player_id: item.id,
    web_name: item.web_name,
    team_short_name: item.team_short_name,
    position: item.position,
    current_price: item.current_price,
    status: item.status,
    is_starting: false,
    bench_order: null,
    is_captain: false,
    is_vice_captain: false,
    projected_points: 0,
    fixtures: [],
    slot_id: null,
    ownership_id: null,
    source_decision_id: null,
    purchase_price_tenths: null,
    provenance: null,
  };
}

function opponentLabel(player: PlanPlayer): string {
  if (player.fixtures.length === 0) {
    return "-";
  }
  return player.fixtures
    .map((fixture) => {
      if (fixture.opponent_team_short_name === null) {
        return "TBD";
      }
      const venue = fixture.is_home === null ? "" : fixture.is_home ? " (H)" : " (A)";
      return `${fixture.opponent_team_short_name}${venue}`;
    })
    .join(", ");
}

export function PlanBoard({ planId }: { planId: number }): JSX.Element {
  const [state, setState] = useState<LoadState>({ type: "loading" });
  const [selectedGameweek, setSelectedGameweek] = useState<number | null>(null);
  const [coordinator, setCoordinator] = useState<PlanSaveCoordinator | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [swapStarterId, setSwapStarterId] = useState<number | null>(null);
  const [transferOutId, setTransferOutId] = useState<number | null>(null);
  const [transferPool, setTransferPool] = useState<PlayerItem[]>([]);
  const [renaming, setRenaming] = useState(false);
  const [renameValue, setRenameValue] = useState("");

  useEffect(() => {
    let cancelled = false;

    async function load(): Promise<void> {
      try {
        const plan = await fetchPlan(planId);
        if (cancelled) {
          return;
        }
        if (plan === null) {
          setState({ type: "missing" });
          return;
        }
        setState({ type: "loaded", plan });
        setCoordinator(getPlanSaveCoordinator(plan));
        setSelectedGameweek((current) => current ?? plan.gameweeks[0]?.gameweek_number ?? null);
      } catch (error) {
        if (!cancelled) {
          setState({
            type: "error",
            message: error instanceof Error ? error.message : "Failed to load plan",
          });
        }
      }
    }

    void load();
    return () => {
      cancelled = true;
    };
  }, [planId]);

  const snapshot = useSyncExternalStore(coordinator?.subscribe ?? EMPTY_SUBSCRIBE,
    coordinator?.getSnapshot ?? EMPTY_SNAPSHOT, EMPTY_SNAPSHOT);
  const plan = snapshot?.displayPlan ?? (state.type === "loaded" ? state.plan : null);
  const gameweek: PlanGameweek | null = useMemo(() => {
    if (plan === null || selectedGameweek === null) {
      return null;
    }
    return plan.gameweeks.find((item) => item.gameweek_number === selectedGameweek) ?? null;
  }, [plan, selectedGameweek]);

  useEffect(() => {
    setSwapStarterId(null);
    setTransferOutId(null);
  }, [gameweek]);

  useEffect(() => {
    if (plan && !plan.gameweeks.some((week) => week.gameweek_number === selectedGameweek)) {
      setSelectedGameweek(plan.gameweeks[0]?.gameweek_number ?? null);
    }
    if (renaming && snapshot?.status === "saved" && snapshot.acknowledged.name === renameValue.trim()) {
      setRenaming(false);
    }
  }, [plan, selectedGameweek, renaming, renameValue, snapshot]);

  function send(intents: PlanIntent[]): void {
    setActionError(null);
    coordinator?.enqueue(intents);
  }

  function handleHorizonChange(field: "start_gameweek" | "end_gameweek", value: number): void {
    setActionError(null);
    coordinator?.enqueue([{ kind: "set_horizon_bound", field, value }]);
  }

  async function handleOpenTransfer(player: PlanPlayer): Promise<void> {
    if (transferOutId === player.player_id) {
      setTransferOutId(null);
      return;
    }

    setTransferOutId(player.player_id);
    setActionError(null);
    try {
      const response = await fetchPlayers({
        position: player.position,
        status: "a",
        sort: "price_desc",
        page_size: 50,
      });
      setTransferPool(response.items);
    } catch (error) {
      setActionError(error instanceof Error ? error.message : "Failed to load transfer options");
    }
  }

  function handleTransfer(outgoing: PlanPlayer, incoming: PlayerItem): void {
    if (!gameweek || !outgoing.ownership_id) return;
    const acquisition = gameweek.decisions.find((decision) => decision.decision_id === outgoing.source_decision_id);
    send([acquisition ? { kind: "edit_transfer", decision_id: acquisition.decision_id,
      incoming_player_id: incoming.id } : { kind: "add_transfer", gameweek_number: gameweek.gameweek_number,
      outgoing_player_id: outgoing.player_id, outgoing_ownership_id: outgoing.ownership_id,
      incoming_player_id: incoming.id }]);
    setTransferOutId(null);
  }

  function handleSwap(starterId: number, benchId: number): void {
    if (!gameweek) return;
    send([{ kind: "swap_lineup_players", gameweek_number: gameweek.gameweek_number,
      first_player_id: starterId, second_player_id: benchId }]);
    setSwapStarterId(null);
  }

  function handleCaptain(playerId: number, role: "captain" | "vice"): void {
    if (!gameweek) return;
    send([{ kind: role === "captain" ? "change_captain" : "change_vice_captain",
      gameweek_number: gameweek.gameweek_number, player_id: playerId }]);
  }

  if (state.type === "loading") {
    return <p className="text-sm text-slate-600">Loading plan...</p>;
  }
  if (state.type === "error") {
    return <p className="text-sm text-red-700">{state.message}</p>;
  }
  if (state.type === "missing") {
    return (
      <p className="text-sm text-slate-600">
        That plan no longer exists.{" "}
        <Link href="/plans" className="underline">
          Back to plans
        </Link>
      </p>
    );
  }

  const currentPlan = plan ?? state.plan;
  const draft = gameweek?.players ?? null;
  const draftChip = gameweek?.chip ?? null;
  const editingUnavailable = currentPlan.foundation_state !== "ready"
    || snapshot?.status === "not_saved" || snapshot?.status === "conflict";
  const starters = (draft ?? []).filter((player) => player.is_starting);
  const bench = (draft ?? [])
    .filter((player) => !player.is_starting)
    .sort((a, b) => (a.bench_order ?? 0) - (b.bench_order ?? 0));

  return (
    <section className="space-y-5">
      <header className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            {renaming ? (
              <div className="flex flex-wrap items-center gap-2">
                <input
                  type="text"
                  aria-label="Plan name"
                  className="w-64 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
                  value={renameValue}
                  onChange={(event) => setRenameValue(event.target.value)}
                />
                <button
                  type="button"
                  className="rounded-md border border-emerald-300 bg-emerald-600 px-2 py-1 text-xs font-medium text-white hover:bg-emerald-500 disabled:opacity-50"
                  disabled={renameValue.trim().length === 0}
                  onClick={() => send([{ kind: "rename_plan", name: renameValue.trim() }])}
                >
                  Save
                </button>
                <button
                  type="button"
                  className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-800 hover:bg-slate-50"
                  onClick={() => setRenaming(false)}
                >
                  Cancel
                </button>
              </div>
            ) : (
              <div className="flex items-center gap-3">
                <h2 className="text-xl font-semibold">{currentPlan.name}</h2>
                <button
                  type="button"
                  aria-label="Rename plan"
                  disabled={editingUnavailable}
                  className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-800 hover:bg-slate-50"
                  onClick={() => {
                    setRenameValue(currentPlan.name);
                    setRenaming(true);
                  }}
                >
                  Rename
                </button>
              </div>
            )}
            <p className="mt-1 text-sm text-slate-600">
              Plan xPts: {currentPlan.total_points?.toFixed(1) ?? "Unavailable"} · Hits taken:{" "}
              {currentPlan.total_points_hit}
            </p>
          </div>

          <div className="flex flex-wrap items-end gap-3">
            <label className="flex flex-col gap-1 text-sm text-slate-700">
              From GW
              <input
                type="number"
                aria-label="Plan start gameweek"
                disabled={editingUnavailable}
                min={1}
                max={38}
                className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
                value={currentPlan.start_gameweek}
                onChange={(event) =>
                  void handleHorizonChange("start_gameweek", Number(event.target.value))
                }
              />
            </label>
            <label className="flex flex-col gap-1 text-sm text-slate-700">
              To GW
              <input
                type="number"
                aria-label="Plan end gameweek"
                disabled={editingUnavailable}
                min={1}
                max={38}
                className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
                value={currentPlan.end_gameweek}
                onChange={(event) =>
                  void handleHorizonChange("end_gameweek", Number(event.target.value))
                }
              />
            </label>
          </div>
        </div>
      </header>

      <nav aria-label="Plan gameweeks" className="flex flex-wrap gap-2">
        {currentPlan.gameweeks.map((item) => (
          <button
            key={item.gameweek_number}
            type="button"
            aria-label={`Gameweek ${item.gameweek_number}`}
            aria-current={item.gameweek_number === selectedGameweek}
            className={`rounded-lg border px-3 py-2 text-left text-xs ${
              item.gameweek_number === selectedGameweek
                ? "border-slate-900 bg-slate-900 text-white"
                : "border-slate-200 bg-white text-slate-800 hover:bg-slate-50"
            }`}
            onClick={() => setSelectedGameweek(item.gameweek_number)}
          >
            <span className="block font-semibold">GW {item.gameweek_number}</span>
            <span className="block">{item.total_points?.toFixed(1) ?? "Unavailable"} xPts</span>
            <span className="block">
              {item.unlimited_transfers ? "Unlimited" : `${item.free_transfers_available} FT`}
              {item.points_hit !== null && item.points_hit > 0 ? ` · -${item.points_hit}` : ""}
            </span>
            {item.chip && <span className="block font-semibold">{item.chip}</span>}
          </button>
        ))}
      </nav>

      <div className="flex flex-wrap items-center gap-3 text-sm">
        <p role="status">{currentPlan.foundation_state !== "ready" ? "Initialization required"
          : snapshot?.status === "saving" ? "Saving..."
          : snapshot?.status === "not_saved" || snapshot?.status === "error" ? "Not saved"
          : snapshot?.status === "conflict" ? "Needs reconciliation" : "Saved"}</p>
        {currentPlan.financial_status.provisional && <span className="text-slate-600">Estimated bases</span>}
        {currentPlan.financial_status.requires_resolution && <span className="text-red-700">Requires resolution</span>}
        {snapshot?.status === "not_saved" && <button type="button" className="rounded-md border px-2 py-1"
          onClick={() => coordinator?.retry()}>Retry Same Edit</button>}
        {snapshot?.status === "conflict" && <button type="button" className="rounded-md border px-2 py-1"
          onClick={() => void coordinator?.revalidate()}>Revalidate With Current Data</button>}
      </div>
      {(snapshot?.message || actionError) && <p role="alert" className="text-sm text-red-700">{snapshot?.message || actionError}</p>}
      {currentPlan.foundation_state !== "ready" && <p className="text-sm text-amber-800">{currentPlan.initialization.reason}</p>}

      {gameweek !== null && draft !== null && (
        <fieldset disabled={editingUnavailable} className="min-w-0 space-y-5">
          <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="text-sm text-slate-700">
                <p className="font-semibold text-slate-900">Gameweek {gameweek.gameweek_number}</p>
                <p>
                  Bank {gameweek.bank?.toFixed(1) ?? "Unavailable"} · Free transfers{" "}
                  {gameweek.unlimited_transfers
                    ? "unlimited"
                    : gameweek.free_transfers_available}{" "}
                  · Transfers made {gameweek.transfers_made}
                  {gameweek.points_hit !== null && gameweek.points_hit > 0 ? ` · Hit -${gameweek.points_hit}` : ""}
                </p>
              </div>
            </div>

            <div className="mt-4 flex flex-wrap gap-2">
              {CHIPS.map((chip) => {
                const availability = gameweek.chip_availability[chip.value];
                const unavailable = !availability || !["available", "planned_here"].includes(availability.state);
                const active = draftChip === chip.value;
                return (
                  <div key={chip.value} className="max-w-64">
                  <button
                    type="button"
                    aria-label={chip.label}
                    aria-pressed={active}
                    title={availability?.reason ?? undefined}
                    disabled={unavailable}
                    className={`rounded-md border px-3 py-1.5 text-xs font-medium disabled:opacity-40 ${
                      active
                        ? "border-slate-900 bg-slate-900 text-white"
                        : "border-slate-300 bg-white text-slate-800 hover:bg-slate-50"
                    }`}
                    onClick={() => send([{ kind: active ? "remove_chip" : "activate_chip",
                      gameweek_number: gameweek.gameweek_number, chip: chip.value }])}
                  >
                    {chip.label}
                  </button>
                  {availability?.reason && <p className="mt-1 text-xs text-slate-600">{availability.reason}</p>}
                  {availability?.state === "planned_elsewhere" && availability.conflicting_gameweek !== null && !gameweek.chip && (
                    <button type="button" className="mt-1 text-xs underline"
                      aria-label={`Move ${chip.label} from GW${availability.conflicting_gameweek} to GW${gameweek.gameweek_number}`}
                      onClick={() => send([{ kind: "move_chip", chip: chip.value,
                        source_gameweek: availability.conflicting_gameweek!, target_gameweek: gameweek.gameweek_number }])}>Move Here</button>
                  )}
                  </div>
                );
              })}
            </div>

            {(gameweek.transfers_in.length > 0 || gameweek.transfers_out.length > 0) && (
              <p className="mt-3 text-xs text-slate-600">
                Transfers: {gameweek.transfers_out.map((item) => item.web_name).join(", ") || "-"}{" "}
                → {gameweek.transfers_in.map((item) => item.web_name).join(", ") || "-"}
              </p>
            )}
            {gameweek.decisions.map((decision) => (
              <button key={decision.decision_id} type="button" className="mt-2 mr-3 text-xs underline"
                aria-label={`Remove transfer ${decision.outgoing_player_id} to ${decision.incoming_player_id}`}
                onClick={() => send([{ kind: "remove_transfer", decision_id: decision.decision_id }])}>Remove Transfer</button>
            ))}
          </section>

          <div className="grid gap-6 lg:grid-cols-[2fr_1fr]">
            <section>
              <h3 className="mb-3 text-sm font-semibold uppercase tracking-wide text-slate-500">
                Starting XI
              </h3>
              <div className="space-y-5">
                {POSITION_ORDER.map((position) => {
                  const rows = starters.filter((player) => player.position === position);
                  if (rows.length === 0) {
                    return null;
                  }

                  return (
                    <section key={position}>
                      <h4 className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">
                        {position}
                      </h4>
                      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
                        {rows.map((player) => (
                          <article
                            key={player.player_id}
                            className="rounded-lg border border-slate-200 p-3"
                          >
                            <div className="flex items-start justify-between gap-3">
                              <div>
                                <p className="text-sm font-semibold text-slate-900">
                                  {player.web_name}
                                </p>
                                <p className="text-xs text-slate-600">
                                  {player.team_short_name} · {player.position} ·{" "}
                                  {player.current_price.toFixed(1)}
                                </p>
                              </div>
                              {(player.is_captain || player.is_vice_captain) && (
                                <span className="rounded-full bg-slate-900 px-2 py-1 text-[10px] font-semibold text-white">
                                  {player.is_captain ? "C" : "VC"}
                                </span>
                              )}
                            </div>
                            <p className="mt-2 text-xs text-slate-600">
                              Opponent: {opponentLabel(player)}
                            </p>
                            <p className="mt-1 text-xs text-slate-600">
                              GW xPts: {player.projected_points.toFixed(1)}
                            </p>
                            <div className="mt-3 flex flex-wrap gap-2 text-xs">
                              <button
                                type="button"
                                aria-label={`Swap ${player.web_name} with bench`}
                                className="rounded-md border border-slate-300 bg-white px-2 py-1 hover:bg-slate-50"
                                onClick={() =>
                                  setSwapStarterId(
                                    swapStarterId === player.player_id ? null : player.player_id,
                                  )
                                }
                              >
                                Swap With Bench
                              </button>
                              <button
                                type="button"
                                aria-label={`Transfer ${player.web_name}`}
                                className="rounded-md border border-slate-300 bg-white px-2 py-1 hover:bg-slate-50"
                                onClick={() => void handleOpenTransfer(player)}
                              >
                                Transfer
                              </button>
                              <button
                                type="button"
                                aria-label={`Make ${player.web_name} captain`}
                                className="rounded-md border border-slate-300 bg-white px-2 py-1 hover:bg-slate-50"
                                onClick={() => handleCaptain(player.player_id, "captain")}
                              >
                                C
                              </button>
                              <button
                                type="button"
                                aria-label={`Make ${player.web_name} vice-captain`}
                                className="rounded-md border border-slate-300 bg-white px-2 py-1 hover:bg-slate-50"
                                onClick={() => handleCaptain(player.player_id, "vice")}
                              >
                                VC
                              </button>
                            </div>

                            {swapStarterId === player.player_id && (
                              <ul className="mt-3 space-y-1 text-xs">
                                {bench.filter((benchPlayer) => gameweek.legal_rearrangements.some((choice) =>
                                  (choice.first_player_id === player.player_id && choice.second_player_id === benchPlayer.player_id)
                                  || (choice.second_player_id === player.player_id && choice.first_player_id === benchPlayer.player_id)
                                )).map((benchPlayer) => (
                                  <li key={benchPlayer.player_id}>
                                    <button
                                      type="button"
                                      aria-label={`Swap ${player.web_name} for ${benchPlayer.web_name}`}
                                      className="w-full rounded-md border border-slate-200 px-2 py-1 text-left hover:bg-slate-50"
                                      onClick={() =>
                                        handleSwap(player.player_id, benchPlayer.player_id)
                                      }
                                    >
                                      {benchPlayer.web_name} ({benchPlayer.position})
                                    </button>
                                  </li>
                                ))}
                              </ul>
                            )}

                            {transferOutId === player.player_id && (
                              <ul className="mt-3 max-h-48 space-y-1 overflow-y-auto text-xs">
                                {transferPool
                                  .filter(
                                    (option) =>
                                      !draft.some(
                                        (selected) => selected.player_id === option.id,
                                      ),
                                  )
                                  .map((option) => (
                                    <li key={option.id}>
                                      <button
                                        type="button"
                                        aria-label={`Transfer in ${option.web_name}`}
                                        className="w-full rounded-md border border-slate-200 px-2 py-1 text-left hover:bg-slate-50"
                                        onClick={() => handleTransfer(player, option)}
                                      >
                                        {option.web_name} · {option.team_short_name} ·{" "}
                                        {option.current_price.toFixed(1)}
                                      </button>
                                    </li>
                                  ))}
                              </ul>
                            )}
                          </article>
                        ))}
                      </div>
                    </section>
                  );
                })}
              </div>
            </section>

            <section>
              <h3 className="mb-3 text-sm font-semibold uppercase tracking-wide text-slate-500">
                Bench
              </h3>
              <div className="space-y-3">
                {bench.map((player) => (
                  <article key={player.player_id} className="rounded-lg border border-slate-200 p-3">
                    <p className="text-sm font-semibold text-slate-900">
                      {player.bench_order}. {player.web_name}
                    </p>
                    <p className="text-xs text-slate-600">
                      {player.team_short_name} · {player.position} ·{" "}
                      {player.current_price.toFixed(1)}
                    </p>
                    <p className="mt-1 text-xs text-slate-600">
                      GW xPts: {player.projected_points.toFixed(1)}
                    </p>
                    <button
                      type="button"
                      aria-label={`Transfer ${player.web_name}`}
                      className="mt-2 rounded-md border border-slate-300 bg-white px-2 py-1 text-xs hover:bg-slate-50"
                      onClick={() => void handleOpenTransfer(player)}
                    >
                      Transfer
                    </button>
                    {transferOutId === player.player_id && (
                      <ul className="mt-3 max-h-48 space-y-1 overflow-y-auto text-xs">
                        {transferPool
                          .filter(
                            (option) =>
                              !draft.some((selected) => selected.player_id === option.id),
                          )
                          .map((option) => (
                            <li key={option.id}>
                              <button
                                type="button"
                                aria-label={`Transfer in ${option.web_name}`}
                                className="w-full rounded-md border border-slate-200 px-2 py-1 text-left hover:bg-slate-50"
                                onClick={() => handleTransfer(player, option)}
                              >
                                {option.web_name} · {option.team_short_name} ·{" "}
                                {option.current_price.toFixed(1)}
                              </button>
                            </li>
                          ))}
                      </ul>
                    )}
                  </article>
                ))}
              </div>
            </section>
          </div>
        </fieldset>
      )}
    </section>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useMemo, useState, useSyncExternalStore } from "react";

import {
  PlanChip,
  PlanGameweek,
  PlanPlayer,
  PlanResponse,
  PlanIntent,
  PlayerItem,
  fetchPlan,
  fetchPlayers,
} from "@/lib/api";
import { PlanSaveCoordinator, getPlanSaveCoordinator } from "@/lib/plan-save-coordinator";

const EMPTY_SUBSCRIBE = () => () => {};
const EMPTY_SNAPSHOT = () => null;

type Position = "GK" | "DEF" | "MID" | "FWD";

type LoadState =
  | { type: "loading" }
  | { type: "error"; message: string }
  | { type: "missing" }
  | { type: "loaded"; plan: PlanResponse };

const POSITION_ORDER: Position[] = ["GK", "DEF", "MID", "FWD"];
const CHIPS: { value: PlanChip; label: string }[] = [
  { value: "WILDCARD", label: "Wildcard" },
  { value: "FREE_HIT", label: "Free Hit" },
  { value: "BENCH_BOOST", label: "Bench Boost" },
  { value: "TRIPLE_CAPTAIN", label: "Triple Captain" },
];
function opponentLabel(player: PlanPlayer): string {
  if (player.fixtures.length === 0) {
    return "-";
  }
  return player.fixtures
    .map((fixture) => {
      if (fixture.opponent_team_short_name === null) {
        return "TBD";
      }
      const venue = fixture.is_home === null ? "" : fixture.is_home ? " (H)" : " (A)";
      return `${fixture.opponent_team_short_name}${venue}`;
    })
    .join(", ");
}

export function PlanBoard({ planId }: { planId: number }): JSX.Element {
  const [state, setState] = useState<LoadState>({ type: "loading" });
  const [selectedGameweek, setSelectedGameweek] = useState<number | null>(null);
  const [coordinator, setCoordinator] = useState<PlanSaveCoordinator | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [swapStarterId, setSwapStarterId] = useState<number | null>(null);
  const [transferOutId, setTransferOutId] = useState<number | null>(null);
  const [transferPool, setTransferPool] = useState<PlayerItem[]>([]);
  const [renaming, setRenaming] = useState(false);
  const [renameValue, setRenameValue] = useState("");

  useEffect(() => {
    let cancelled = false;

    async function load(): Promise<void> {
      try {
        const plan = await fetchPlan(planId);
        if (cancelled) {
          return;
        }
        if (plan === null) {
          setState({ type: "missing" });
          return;
        }
        setState({ type: "loaded", plan });
        setCoordinator(getPlanSaveCoordinator(plan));
        setSelectedGameweek((current) => current ?? plan.gameweeks[0]?.gameweek_number ?? null);
      } catch (error) {
        if (!cancelled) {
          setState({
            type: "error",
            message: error instanceof Error ? error.message : "Failed to load plan",
          });
        }
      }
    }

    void load();
    return () => {
      cancelled = true;
    };
  }, [planId]);

  const snapshot = useSyncExternalStore(coordinator?.subscribe ?? EMPTY_SUBSCRIBE,
    coordinator?.getSnapshot ?? EMPTY_SNAPSHOT, EMPTY_SNAPSHOT);
  const plan = snapshot?.displayPlan ?? (state.type === "loaded" ? state.plan : null);
  const gameweek: PlanGameweek | null = useMemo(() => {
    if (plan === null || selectedGameweek === null) {
      return null;
    }
    return plan.gameweeks.find((item) => item.gameweek_number === selectedGameweek) ?? null;
  }, [plan, selectedGameweek]);

  useEffect(() => {
    setSwapStarterId(null);
    setTransferOutId(null);
  }, [gameweek]);

  useEffect(() => {
    if (plan && !plan.gameweeks.some((week) => week.gameweek_number === selectedGameweek)) {
      setSelectedGameweek(plan.gameweeks[0]?.gameweek_number ?? null);
    }
    if (renaming && snapshot?.status === "saved" && snapshot.acknowledged.name === renameValue.trim()) {
      setRenaming(false);
    }
  }, [plan, selectedGameweek, renaming, renameValue, snapshot]);

  function send(intents: PlanIntent[]): void {
    setActionError(null);
    coordinator?.enqueue(intents);
  }

  function handleHorizonChange(field: "start_gameweek" | "end_gameweek", value: number): void {
    setActionError(null);
    coordinator?.enqueue([{ kind: "set_horizon_bound", field, value }]);
  }

  async function handleOpenTransfer(player: PlanPlayer): Promise<void> {
    if (transferOutId === player.player_id) {
      setTransferOutId(null);
      return;
    }

    setTransferOutId(player.player_id);
    setActionError(null);
    try {
      const response = await fetchPlayers({
        position: player.position,
        status: "a",
        sort: "price_desc",
        page_size: 50,
      });
      setTransferPool(response.items);
    } catch (error) {
      setActionError(error instanceof Error ? error.message : "Failed to load transfer options");
    }
  }

  function handleTransfer(outgoing: PlanPlayer, incoming: PlayerItem): void {
    if (!gameweek || !outgoing.ownership_id) return;
    const acquisition = gameweek.decisions.find((decision) => decision.decision_id === outgoing.source_decision_id);
    send([acquisition ? { kind: "edit_transfer", decision_id: acquisition.decision_id,
      incoming_player_id: incoming.id } : { kind: "add_transfer", gameweek_number: gameweek.gameweek_number,
      outgoing_player_id: outgoing.player_id, outgoing_ownership_id: outgoing.ownership_id,
      incoming_player_id: incoming.id }]);
    setTransferOutId(null);
  }

  function handleSwap(starterId: number, benchId: number): void {
    if (!gameweek) return;
    send([{ kind: "swap_lineup_players", gameweek_number: gameweek.gameweek_number,
      first_player_id: starterId, second_player_id: benchId }]);
    setSwapStarterId(null);
  }

  function handleCaptain(playerId: number, role: "captain" | "vice"): void {
    if (!gameweek) return;
    send([{ kind: role === "captain" ? "change_captain" : "change_vice_captain",
      gameweek_number: gameweek.gameweek_number, player_id: playerId }]);
  }

  if (state.type === "loading") {
    return <p className="text-sm text-slate-600">Loading plan...</p>;
  }
  if (state.type === "error") {
    return <p className="text-sm text-red-700">{state.message}</p>;
  }
  if (state.type === "missing") {
    return (
      <p className="text-sm text-slate-600">
        That plan no longer exists.{" "}
        <Link href="/plans" className="underline">
          Back to plans
        </Link>
      </p>
    );
  }

  const currentPlan = plan ?? state.plan;
  const draft = gameweek?.players ?? null;
  const draftChip = gameweek?.chip ?? null;
  const editingUnavailable = currentPlan.foundation_state !== "ready"
    || snapshot?.status === "not_saved" || snapshot?.status === "conflict";
  const starters = (draft ?? []).filter((player) => player.is_starting);
  const bench = (draft ?? [])
    .filter((player) => !player.is_starting)
    .sort((a, b) => (a.bench_order ?? 0) - (b.bench_order ?? 0));

  return (
    <section className="space-y-5">
      <header className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            {renaming ? (
              <div className="flex flex-wrap items-center gap-2">
                <input
                  type="text"
                  aria-label="Plan name"
                  className="w-64 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
                  value={renameValue}
                  onChange={(event) => setRenameValue(event.target.value)}
                />
                <button
                  type="button"
                  className="rounded-md border border-emerald-300 bg-emerald-600 px-2 py-1 text-xs font-medium text-white hover:bg-emerald-500 disabled:opacity-50"
                  disabled={renameValue.trim().length === 0}
                  onClick={() => send([{ kind: "rename_plan", name: renameValue.trim() }])}
                >
                  Save
                </button>
                <button
                  type="button"
                  className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-800 hover:bg-slate-50"
                  onClick={() => setRenaming(false)}
                >
                  Cancel
                </button>
              </div>
            ) : (
              <div className="flex items-center gap-3">
                <h2 className="text-xl font-semibold">{currentPlan.name}</h2>
                <button
                  type="button"
                  aria-label="Rename plan"
                  disabled={editingUnavailable}
                  className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-800 hover:bg-slate-50"
                  onClick={() => {
                    setRenameValue(currentPlan.name);
                    setRenaming(true);
                  }}
                >
                  Rename
                </button>
              </div>
            )}
            <p className="mt-1 text-sm text-slate-600">
              Plan xPts: {currentPlan.total_points?.toFixed(1) ?? "Unavailable"} · Hits taken:{" "}
              {currentPlan.total_points_hit}
            </p>
          </div>

          <div className="flex flex-wrap items-end gap-3">
            <label className="flex flex-col gap-1 text-sm text-slate-700">
              From GW
              <input
                type="number"
                aria-label="Plan start gameweek"
                disabled={editingUnavailable}
                min={1}
                max={38}
                className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
                value={currentPlan.start_gameweek}
                onChange={(event) =>
                  void handleHorizonChange("start_gameweek", Number(event.target.value))
                }
              />
            </label>
            <label className="flex flex-col gap-1 text-sm text-slate-700">
              To GW
              <input
                type="number"
                aria-label="Plan end gameweek"
                disabled={editingUnavailable}
                min={1}
                max={38}
                className="w-24 rounded-md border border-slate-300 px-2 py-1.5 text-sm text-slate-900"
                value={currentPlan.end_gameweek}
                onChange={(event) =>
                  void handleHorizonChange("end_gameweek", Number(event.target.value))
                }
              />
            </label>
          </div>
        </div>
      </header>

      <nav aria-label="Plan gameweeks" className="flex flex-wrap gap-2">
        {currentPlan.gameweeks.map((item) => (
          <button
            key={item.gameweek_number}
            type="button"
            aria-label={`Gameweek ${item.gameweek_number}`}
            aria-current={item.gameweek_number === selectedGameweek}
            className={`rounded-lg border px-3 py-2 text-left text-xs ${
              item.gameweek_number === selectedGameweek
                ? "border-slate-900 bg-slate-900 text-white"
                : "border-slate-200 bg-white text-slate-800 hover:bg-slate-50"
            }`}
            onClick={() => setSelectedGameweek(item.gameweek_number)}
          >
            <span className="block font-semibold">GW {item.gameweek_number}</span>
            <span className="block">{item.total_points?.toFixed(1) ?? "Unavailable"} xPts</span>
            <span className="block">
              {item.unlimited_transfers ? "Unlimited" : `${item.free_transfers_available} FT`}
              {item.points_hit !== null && item.points_hit > 0 ? ` · -${item.points_hit}` : ""}
            </span>
            {item.chip && <span className="block font-semibold">{item.chip}</span>}
          </button>
        ))}
      </nav>

      <div className="flex flex-wrap items-center gap-3 text-sm">
        <p role="status">{currentPlan.foundation_state !== "ready" ? "Initialization required"
          : snapshot?.status === "saving" ? "Saving..."
          : snapshot?.status === "not_saved" || snapshot?.status === "error" ? "Not saved"
          : snapshot?.status === "conflict" ? "Needs reconciliation" : "Saved"}</p>
        {currentPlan.financial_status.provisional && <span className="text-slate-600">Estimated bases</span>}
        {currentPlan.financial_status.requires_resolution && <span className="text-red-700">Requires resolution</span>}
        {snapshot?.status === "not_saved" && <button type="button" className="rounded-md border px-2 py-1"
          onClick={() => coordinator?.retry()}>Retry Same Edit</button>}
        {snapshot?.status === "conflict" && <button type="button" className="rounded-md border px-2 py-1"
          onClick={() => void coordinator?.revalidate()}>Revalidate With Current Data</button>}
      </div>
      {(snapshot?.message || actionError) && <p role="alert" className="text-sm text-red-700">{snapshot?.message || actionError}</p>}
      {currentPlan.foundation_state !== "ready" && <p className="text-sm text-amber-800">{currentPlan.initialization.reason}</p>}

      {gameweek !== null && draft !== null && (
        <fieldset disabled={editingUnavailable} className="min-w-0 space-y-5">
          <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="text-sm text-slate-700">
                <p className="font-semibold text-slate-900">Gameweek {gameweek.gameweek_number}</p>
                <p>
                  Bank {gameweek.bank?.toFixed(1) ?? "Unavailable"} · Free transfers{" "}
                  {gameweek.unlimited_transfers
                    ? "unlimited"
                    : gameweek.free_transfers_available}{" "}
                  · Transfers made {gameweek.transfers_made}
                  {gameweek.points_hit !== null && gameweek.points_hit > 0 ? ` · Hit -${gameweek.points_hit}` : ""}
                </p>
              </div>
            </div>

            <div className="mt-4 flex flex-wrap gap-2">
              {CHIPS.map((chip) => {
                const availability = gameweek.chip_availability[chip.value];
                const unavailable = !availability || !["available", "planned_here"].includes(availability.state);
                const active = draftChip === chip.value;
                return (
                  <div key={chip.value} className="max-w-64">
                  <button
                    type="button"
                    aria-label={chip.label}
                    aria-pressed={active}
                    title={availability?.reason ?? undefined}
                    disabled={unavailable}
                    className={`rounded-md border px-3 py-1.5 text-xs font-medium disabled:opacity-40 ${
                      active
                        ? "border-slate-900 bg-slate-900 text-white"
                        : "border-slate-300 bg-white text-slate-800 hover:bg-slate-50"
                    }`}
                    onClick={() => send([{ kind: active ? "remove_chip" : "activate_chip",
                      gameweek_number: gameweek.gameweek_number, chip: chip.value }])}
                  >
                    {chip.label}
                  </button>
                  {availability?.reason && <p className="mt-1 text-xs text-slate-600">{availability.reason}</p>}
                  {availability?.state === "planned_elsewhere" && availability.conflicting_gameweek !== null && !gameweek.chip && (
                    <button type="button" className="mt-1 text-xs underline"
                      aria-label={`Move ${chip.label} from GW${availability.conflicting_gameweek} to GW${gameweek.gameweek_number}`}
                      onClick={() => send([{ kind: "move_chip", chip: chip.value,
                        source_gameweek: availability.conflicting_gameweek!, target_gameweek: gameweek.gameweek_number }])}>Move Here</button>
                  )}
                  </div>
                );
              })}
            </div>

            {(gameweek.transfers_in.length > 0 || gameweek.transfers_out.length > 0) && (
              <p className="mt-3 text-xs text-slate-600">
                Transfers: {gameweek.transfers_out.map((item) => item.web_name).join(", ") || "-"}{" "}
                → {gameweek.transfers_in.map((item) => item.web_name).join(", ") || "-"}
              </p>
            )}
            {gameweek.decisions.map((decision) => (
              <button key={decision.decision_id} type="button" className="mt-2 mr-3 text-xs underline"
                aria-label={`Remove transfer ${decision.outgoing_player_id} to ${decision.incoming_player_id}`}
                onClick={() => send([{ kind: "remove_transfer", decision_id: decision.decision_id }])}>Remove Transfer</button>
            ))}
          </section>

          <div className="grid gap-6 lg:grid-cols-[2fr_1fr]">
            <section>
              <h3 className="mb-3 text-sm font-semibold uppercase tracking-wide text-slate-500">
                Starting XI
              </h3>
              <div className="space-y-5">
                {POSITION_ORDER.map((position) => {
                  const rows = starters.filter((player) => player.position === position);
                  if (rows.length === 0) {
                    return null;
                  }

                  return (
                    <section key={position}>
                      <h4 className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">
                        {position}
                      </h4>
                      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
                        {rows.map((player) => (
                          <article
                            key={player.player_id}
                            className="rounded-lg border border-slate-200 p-3"
                          >
                            <div className="flex items-start justify-between gap-3">
                              <div>
                                <p className="text-sm font-semibold text-slate-900">
                                  {player.web_name}
                                </p>
                                <p className="text-xs text-slate-600">
                                  {player.team_short_name} · {player.position} ·{" "}
                                  {player.current_price.toFixed(1)}
                                </p>
                              </div>
                              {(player.is_captain || player.is_vice_captain) && (
                                <span className="rounded-full bg-slate-900 px-2 py-1 text-[10px] font-semibold text-white">
                                  {player.is_captain ? "C" : "VC"}
                                </span>
                              )}
                            </div>
                            <p className="mt-2 text-xs text-slate-600">
                              Opponent: {opponentLabel(player)}
                            </p>
                            <p className="mt-1 text-xs text-slate-600">
                              GW xPts: {player.projected_points.toFixed(1)}
                            </p>
                            <div className="mt-3 flex flex-wrap gap-2 text-xs">
                              <button
                                type="button"
                                aria-label={`Swap ${player.web_name} with bench`}
                                className="rounded-md border border-slate-300 bg-white px-2 py-1 hover:bg-slate-50"
                                onClick={() =>
                                  setSwapStarterId(
                                    swapStarterId === player.player_id ? null : player.player_id,
                                  )
                                }
                              >
                                Swap With Bench
                              </button>
                              <button
                                type="button"
                                aria-label={`Transfer ${player.web_name}`}
                                className="rounded-md border border-slate-300 bg-white px-2 py-1 hover:bg-slate-50"
                                onClick={() => void handleOpenTransfer(player)}
                              >
                                Transfer
                              </button>
                              <button
                                type="button"
                                aria-label={`Make ${player.web_name} captain`}
                                className="rounded-md border border-slate-300 bg-white px-2 py-1 hover:bg-slate-50"
                                onClick={() => handleCaptain(player.player_id, "captain")}
                              >
                                C
                              </button>
                              <button
                                type="button"
                                aria-label={`Make ${player.web_name} vice-captain`}
                                className="rounded-md border border-slate-300 bg-white px-2 py-1 hover:bg-slate-50"
                                onClick={() => handleCaptain(player.player_id, "vice")}
                              >
                                VC
                              </button>
                            </div>

                            {swapStarterId === player.player_id && (
                              <ul className="mt-3 space-y-1 text-xs">
                                {bench.filter((benchPlayer) => gameweek.legal_rearrangements.some((choice) =>
                                  (choice.first_player_id === player.player_id && choice.second_player_id === benchPlayer.player_id)
                                  || (choice.second_player_id === player.player_id && choice.first_player_id === benchPlayer.player_id)
                                )).map((benchPlayer) => (
                                  <li key={benchPlayer.player_id}>
                                    <button
                                      type="button"
                                      aria-label={`Swap ${player.web_name} for ${benchPlayer.web_name}`}
                                      className="w-full rounded-md border border-slate-200 px-2 py-1 text-left hover:bg-slate-50"
                                      onClick={() =>
                                        handleSwap(player.player_id, benchPlayer.player_id)
                                      }
                                    >
                                      {benchPlayer.web_name} ({benchPlayer.position})
                                    </button>
                                  </li>
                                ))}
                              </ul>
                            )}

                            {transferOutId === player.player_id && (
                              <ul className="mt-3 max-h-48 space-y-1 overflow-y-auto text-xs">
                                {transferPool
                                  .filter(
                                    (option) =>
                                      !draft.some(
                                        (selected) => selected.player_id === option.id,
                                      ),
                                  )
                                  .map((option) => (
                                    <li key={option.id}>
                                      <button
                                        type="button"
                                        aria-label={`Transfer in ${option.web_name}`}
                                        className="w-full rounded-md border border-slate-200 px-2 py-1 text-left hover:bg-slate-50"
                                        onClick={() => handleTransfer(player, option)}
                                      >
                                        {option.web_name} · {option.team_short_name} ·{" "}
                                        {option.current_price.toFixed(1)}
                                      </button>
                                    </li>
                                  ))}
                              </ul>
                            )}
                          </article>
                        ))}
                      </div>
                    </section>
                  );
                })}
              </div>
            </section>

            <section>
              <h3 className="mb-3 text-sm font-semibold uppercase tracking-wide text-slate-500">
                Bench
              </h3>
              <div className="space-y-3">
                {bench.map((player) => (
                  <article key={player.player_id} className="rounded-lg border border-slate-200 p-3">
                    <p className="text-sm font-semibold text-slate-900">
                      {player.bench_order}. {player.web_name}
                    </p>
                    <p className="text-xs text-slate-600">
                      {player.team_short_name} · {player.position} ·{" "}
                      {player.current_price.toFixed(1)}
                    </p>
                    <p className="mt-1 text-xs text-slate-600">
                      GW xPts: {player.projected_points.toFixed(1)}
                    </p>
                    <button
                      type="button"
                      aria-label={`Transfer ${player.web_name}`}
                      className="mt-2 rounded-md border border-slate-300 bg-white px-2 py-1 text-xs hover:bg-slate-50"
                      onClick={() => void handleOpenTransfer(player)}
                    >
                      Transfer
                    </button>
                    {transferOutId === player.player_id && (
                      <ul className="mt-3 max-h-48 space-y-1 overflow-y-auto text-xs">
                        {transferPool
                          .filter(
                            (option) =>
                              !draft.some((selected) => selected.player_id === option.id),
                          )
                          .map((option) => (
                            <li key={option.id}>
                              <button
                                type="button"
                                aria-label={`Transfer in ${option.web_name}`}
                                className="w-full rounded-md border border-slate-200 px-2 py-1 text-left hover:bg-slate-50"
                                onClick={() => handleTransfer(player, option)}
                              >
                                {option.web_name} · {option.team_short_name} ·{" "}
                                {option.current_price.toFixed(1)}
                              </button>
                            </li>
                          ))}
                      </ul>
                    )}
                  </article>
                ))}
              </div>
            </section>
          </div>
        </fieldset>
      )}
    </section>
  );
}

import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { PlanBoard } from "@/components/plans/plan-board";
import { buildPlannerPlan, plannerIdentity } from "../fixtures/planner";

type PlanGameweekOverrides = {
  gameweek_number: number;
  chip?: string | null;
  free_transfers_available?: number;
  unlimited_transfers?: boolean;
  transfers_made?: number;
  points_hit?: number;
  total_points?: number;
};

function buildPlayers() {
  return [
    { player_id: 1, web_name: "GK One", position: "GK", is_starting: true, bench_order: null },
    { player_id: 2, web_name: "GK Two", position: "GK", is_starting: false, bench_order: 1 },
    { player_id: 3, web_name: "DEF One", position: "DEF", is_starting: true, bench_order: null },
    { player_id: 4, web_name: "DEF Two", position: "DEF", is_starting: true, bench_order: null },
    { player_id: 5, web_name: "DEF Three", position: "DEF", is_starting: true, bench_order: null },
    { player_id: 6, web_name: "DEF Four", position: "DEF", is_starting: true, bench_order: null },
    { player_id: 7, web_name: "DEF Five", position: "DEF", is_starting: false, bench_order: 2 },
    { player_id: 8, web_name: "MID One", position: "MID", is_starting: true, bench_order: null },
    { player_id: 9, web_name: "MID Two", position: "MID", is_starting: true, bench_order: null },
    { player_id: 10, web_name: "MID Three", position: "MID", is_starting: true, bench_order: null },
    { player_id: 11, web_name: "MID Four", position: "MID", is_starting: true, bench_order: null },
    { player_id: 12, web_name: "MID Five", position: "MID", is_starting: false, bench_order: 3 },
    { player_id: 13, web_name: "FWD One", position: "FWD", is_starting: true, bench_order: null },
    { player_id: 14, web_name: "FWD Two", position: "FWD", is_starting: true, bench_order: null },
    { player_id: 15, web_name: "FWD Three", position: "FWD", is_starting: false, bench_order: 4 },
  ].map((player) => ({
    ...player,
    team_short_name: "ARS",
    current_price: 5.0,
    status: "a",
    is_captain: player.player_id === 13,
    is_vice_captain: player.player_id === 9,
    projected_points: player.is_starting ? 4 : 2,
    slot_id: plannerIdentity(player.player_id),
    ownership_id: plannerIdentity(1000 + player.player_id),
    source_decision_id: null,
    purchase_price_tenths: 50,
    provenance: { source: "stored_market", original_price_tenths: 50, basis_kind: "starting", confirmation: "assumed" },
    fixtures: [
      {
        fixture_id: player.player_id,
        projected_points: player.is_starting ? 4 : 2,
        kickoff_time: "2026-08-15T15:00:00+00:00",
        opponent_team_short_name: "CHE",
        is_home: true,
      },
    ],
  }));
}

function buildPlan(gameweeks: PlanGameweekOverrides[] = [{ gameweek_number: 1 }]) {
  const canonical = buildPlannerPlan(gameweeks[0].gameweek_number, gameweeks[gameweeks.length - 1].gameweek_number);
  return {
    ...canonical,
    name: "No Haaland GW1",
