async function readPlannerMutation(response: Response): Promise<PlanMutationResponse> {
  const body = await response.json();
  if (!response.ok) {
    const detail = body.detail;
    throw new PlannerMutationError(response.status,
      detail && !Array.isArray(detail) && typeof detail.code === "string"
        ? detail : { code: "invalid_request", message: "Planner request rejected" });
  }
  if (!["committed", "already_committed", "accepted_not_saved"].includes(body.status)
      || !Number.isInteger(body.plan?.revision) || typeof body.mutation_id !== "string") {
    throw new PlannerMutationError(503, { code: "outcome_unknown", message: "Invalid response; reconcile the same edit" });
  }
  return body as PlanMutationResponse;
}

export async function mutatePlan(planId: number, envelope: PlanMutationEnvelope): Promise<PlanMutationResponse> {
  return readPlannerMutation(await fetch(`${API_BASE_URL}/plans/${planId}/mutations`, {
    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(envelope),
  }));
}

export async function fetchPlanMutation(planId: number, mutationId: string): Promise<PlanMutationResponse> {
  return readPlannerMutation(await fetch(`${API_BASE_URL}/plans/${planId}/mutations/${mutationId}`));
}

