    initial_bank: 0.5,
    initial_free_transfers: 1,
    total_points: 50,
    total_points_hit: 0,
    gameweeks: gameweeks.map((gameweek, index) => ({
      ...canonical.gameweeks[index],
      chip: null,
      bank: 0.5,
      free_transfers_available: 1,
      unlimited_transfers: false,
      transfers_made: 0,
      points_hit: 0,
      starting_points: 44,
      bench_points: 8,
