function mockFetch(
  plan: ReturnType<typeof buildPlan>,
  saved?: ReturnType<typeof buildPlan>,
) {
  const saveCalls: { url: string; body: unknown }[] = [];

  vi.spyOn(global, "fetch").mockImplementation(async (input, init) => {
    const url = String(input);

    if (init?.method === "POST") {
      saveCalls.push({ url, body: JSON.parse(String(init.body)) });
      const envelope = JSON.parse(String(init.body));
      return new Response(
        JSON.stringify({
          status: "committed",
          mutation_id: envelope.mutation_id,
          committed_revision: envelope.expected_revision + 1,
          plan: {
            ...(saved ?? plan),
            revision: envelope.expected_revision + 1,
          },
          candidate: null,
        }),
        { status: 200 },
      );
    }
    if (url.includes("/players?")) {
      return new Response(
        JSON.stringify({
          items: [
            {
              id: 99,
              web_name: "New Mid",
              first_name: "New",
              second_name: "Mid",
              team_name: "Chelsea",
              team_short_name: "CHE",
              position: "MID",
              current_price: 5.0,
              status: "a",
            },
          ],
          total: 1,
          page: 1,
          page_size: 50,
        }),
        { status: 200 },
      );
    }

    return new Response(JSON.stringify(plan), { status: 200 });
  });

  return saveCalls;
}

