test.use({ baseURL: process.env.PLANNER_BASE_URL ?? "http://127.0.0.1:3000" });

const HEADERS = {
  "access-control-allow-origin": "*",
  "access-control-allow-headers": "content-type",
  "access-control-allow-methods": "GET,POST,OPTIONS",
};

function startingEdit(plan: PlanResponse, intents: PlanIntent[]): PlanResponse {
  if (!plan.starting_state) throw new Error("Missing fixture boundary");
  for (const intent of intents) {
    if (intent.kind === "set_starting_transfers") {
      plan.starting_state.free_transfers = intent.value;
      plan.gameweeks[0].free_transfers_available = intent.value;
    } else if (intent.kind === "set_starting_chips") {
      if (intent.used_chips.includes("TRIPLE_CAPTAIN")) throw new Error("Gameweek 18: Triple Captain is already planned");
      plan.starting_state.used_chips = intent.used_chips;
      plan.starting_state.free_hit_gameweek_19 = intent.free_hit_gameweek_19;
      for (const week of plan.gameweeks) {
        if (week.gameweek_number < 20) week.chip_availability.WILDCARD = intent.used_chips.includes("WILDCARD")
          ? { state: "used_before", reason: "Used before this plan", conflicting_gameweek: null }
          : { state: "available", reason: null, conflicting_gameweek: null };
        if (plan.start_gameweek === 20 && week.gameweek_number === 20 && intent.free_hit_gameweek_19) {
          week.chip_availability.FREE_HIT = { state: "rule_unavailable", reason: "Free Hit conflicts with gameweek 19", conflicting_gameweek: 19 };
        }
      }
    } else if (intent.kind === "correct_purchase_price" || intent.kind === "confirm_purchase_price") {
      const player = plan.starting_state.players.find(item => item.ownership_id === intent.ownership_id);
      if (!player) throw new Error("Missing fixture ownership");
      if (intent.kind === "correct_purchase_price") player.purchase_price_tenths = intent.price_tenths;
      if (player.provenance.basis_kind === "starting") player.provenance.confirmation = "user_confirmed";
    } else if (intent.kind === "change_captain") {
      const week = plan.gameweeks.find(item => item.gameweek_number === intent.gameweek_number)!;
      week.players.forEach(player => { player.is_captain = player.player_id === intent.player_id; });
    } else {
      throw new Error(`Unexpected fixture intent ${intent.kind}`);
    }
  }
  return plan;
}

async function installPlanner(
  page: Page,
  initial: PlanResponse,
  apply = startingEdit,
  options: { creation?: boolean; readGate?: Promise<void> } = {},
) {
  const server = createPlannerFixture(initial, apply);
  let created = !options.creation;
  const methods: string[] = [];
  const creations: unknown[] = [];
  let myTeamBank = 1;
  const myTeamReads: string[] = [];
  await page.route("http://127.0.0.1:8000/**", async route => {
    const request = route.request();
    const path = new URL(request.url()).pathname;
    const method = request.method();
    if (method === "OPTIONS") return route.fulfill({ status: 204, headers: HEADERS });
    methods.push(method);
    if (method === "POST" && path.endsWith("/mutations")) {
      const envelope = request.postDataJSON();
      try {
        return await route.fulfill({ json: { ...server.mutate(envelope), mutation_id: envelope.mutation_id, candidate: null }, headers: HEADERS });
      } catch (error) {
        return route.fulfill({ status: 422, json: { detail: { code: "chip_used_before", message: String(error) } }, headers: HEADERS });
      }
    }
    if (method === "POST" && path === "/plans") {
      creations.push(request.postDataJSON());
      created = true;
      return route.fulfill({ status: 201, json: server.read(), headers: HEADERS });
    }
    if (method !== "GET") throw new Error(`Unexpected writer ${method}`);
    if (path === "/plans") return route.fulfill({ json: { plans: created ? [server.read()] : [] }, headers: HEADERS });
    if (path === "/players") return route.fulfill({ json: { items: [{ id: 104, web_name: "Replacement P104", position: "DEF", current_price: 5.2, status: "a", team_short_name: "NEW", first_name: "Replacement", second_name: "P104", team_name: "New Team" }], total: 1, page: 1, page_size: 50 }, headers: HEADERS });
    if (path === "/my-team") {
      myTeamReads.push(path);
      return route.fulfill({ json: { bank: myTeamBank, free_transfers: 5, players: [] }, headers: HEADERS });
    }
    if (options.readGate) await options.readGate;
    return route.fulfill({ json: server.read(), headers: HEADERS });
  });
  return { ...server, methods, creations, myTeamReads, changeMyTeam: () => { myTeamBank = 99; } };
}

async function saved(page: Page) {
  await expect(page.getByRole("status").filter({ hasText: /^Saved$/ })).toBeVisible();
}

async function editNumber(page: Page, label: string, value: string) {
  await page.getByLabel(label, { exact: true }).fill(value);
  await page.getByLabel(label, { exact: true }).press("Tab");
  await saved(page);
}

