for (const start of [1, 20, 25]) {
  test(`US1 boundary controls and FT0 at GW${start}`, async ({ page }) => {
    const initial = buildPlannerPlan(start, start + 1);
    if (start === 1) for (const chip of ["WILDCARD", "FREE_HIT"] as const) {
      initial.gameweeks[0].chip_availability[chip] = { state: "rule_unavailable", reason: `${chip} is unavailable in gameweek 1`, conflicting_gameweek: null };
    }
    await installPlanner(page, initial);
    await page.goto(`/plans/${initial.plan_id}`);
    await expect(page.getByRole("heading", { name: `Starting state at GW${start}` })).toBeVisible();
    if (start === 1) {
      await expect(page.getByText("Free transfers: N/A (unlimited)")).toBeVisible();
      await expect(page.getByLabel("Starting free transfers", { exact: true })).toHaveCount(0);
      await expect(page.getByRole("button", { name: "Wildcard", exact: true })).toBeDisabled();
      await expect(page.getByRole("button", { name: "Free Hit", exact: true })).toBeDisabled();
    } else {
      await editNumber(page, "Starting free transfers", "0");
      await expect(page.getByText(/Bank 1.0 · Free transfers 0/)).toBeVisible();
    }
    if (start === 20) {
      await expect(page.getByLabel("Wildcard used before this plan", { exact: true })).toHaveCount(0);
      await page.getByLabel("Free Hit used in GW19", { exact: true }).click();
      await saved(page);
      await expect(page.getByRole("button", { name: "Free Hit", exact: true })).toBeDisabled();
      await expect(page.getByText("Free Hit conflicts with gameweek 19", { exact: true })).toBeVisible();
    }
    if (start === 25) await expect(page.getByRole("group", { name: "Chips used before GW25 (GW20-38)" })).toBeVisible();
  });
}

test("foundation loading and uninitialized plans remain read-only", async ({ page }) => {
  const gate = deferred<void>();
  const initial = buildPlannerPlan();
  initial.foundation_state = "legacy_pending";
  initial.starting_state = null;
  initial.initialization = { ready: false, reason: "Explicit legacy initialization required" };
  const server = await installPlanner(page, initial, startingEdit, { readGate: gate.promise });
  await page.goto(`/plans/${initial.plan_id}`);
  await expect(page.getByText("Loading plan...", { exact: true })).toBeVisible();
  gate.resolve();
  await expect(page.getByRole("status").filter({ hasText: /^Initialization required$/ })).toBeVisible();
  await expect(page.getByText("Explicit legacy initialization required")).toBeVisible();
  await expect(page.getByRole("button", { name: "Make P4 captain", exact: true })).toBeDisabled();
  expect(server.requests).toEqual([]);
});

